/* Pedido compacto para tablet: nombre, precio y controles siempre visibles */
.order-item {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  gap: 5px 9px;
  align-items: center;
  padding: 10px 11px;
}
.oi-em {
  grid-column: 1;
  grid-row: 1 / 4;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  font-size: 23px;
}
.oi-em img { border-radius: 10px; }
.oi-info {
  grid-column: 2;
  grid-row: 1;
  width: 100%;
}
.oi-name {
  font-size: 13px;
  line-height: 1.2;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
