  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 5px;
  min-width: 0;
}
.oi-unit {
  font-size: 10px;
  white-space: nowrap;
}
.oi-tot {
  min-width: 0;
  font-size: 13px;
  line-height: 1.1;
  white-space: nowrap;
  text-align: right;
}
.oi-ctrl {
  grid-column: 2;
  grid-row: 2 / 4;
  justify-content: flex-start;
  gap: 5px;
}
.qty-btn {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  font-size: 16px;
}
.oi-qty {
  min-width: 20px;
  font-size: 15px;
}

