  top: 10px;
  right: 10px;

  width: 22px;
  height: 22px;

  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  background: rgba(255,255,255,0.08);

  border: 1px solid rgba(255,255,255,0.10);

  color: transparent;

  font-size: 11px;
  font-weight: 900;

  transition: all .15s;
}


.rep-main-option.active .rep-main-option-check {
