  font-size: 18px;
  font-weight: 900;

  letter-spacing: -.02em;
}


.rep-flow-close {
  width: 34px;
  height: 34px;

  flex-shrink: 0;

  border-radius: 11px;

  border: 1px solid rgba(255,255,255,0.10);

  background: rgba(255,255,255,0.04);

  color: rgba(255,255,255,0.50);

  font-family: inherit;

  font-size: 20px;

  line-height: 1;

  cursor: pointer;

  transition: all .15s;
}


.rep-flow-close:hover {
  background: rgba(255,255,255,0.10);

  border-color: rgba(255,255,255,0.20);

  color: #fff;
}


/* =========================================================
   CALENDARIO
   ========================================================= */

.rep-date-dialog .rep-calendar {
  width: 100%;

  padding: 14px;

  border-radius: 18px;

  border: 1px solid rgba(255,255,255,0.08);

  background: rgba(255,255,255,0.025);

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.05);
}


.rep-date-dialog .rep-calendar-head {
  display: grid;

  grid-template-columns: 36px 1fr 36px;

  align-items: center;

  gap: 8px;

  margin-bottom: 14px;
}


.rep-date-dialog .rep-calendar-head strong {
  text-align: center;

  color: #fff;

  font-size: 14px;
  font-weight: 850;

  text-transform: uppercase;

  letter-spacing: .04em;
}


.rep-date-dialog .rep-cal-nav {
  width: 36px;
  height: 36px;

  border-radius: 11px;

  border: 1px solid rgba(255,255,255,0.09);

  background: rgba(255,255,255,0.04);

  color: rgba(255,255,255,0.68);

  font-family: inherit;

  font-size: 23px;

  line-height: 1;

  cursor: pointer;

  transition: all .15s;
}


.rep-date-dialog .rep-cal-nav:hover {
  background: rgba(255,255,255,0.10);

  color: #fff;

  transform: none;
}


/* días de la semana */
.rep-date-dialog .rep-cal-weekdays {
  display: grid;

  grid-template-columns: repeat(7, 1fr);

  gap: 4px;

  margin-bottom: 6px;

  color: rgba(255,255,255,0.28);

  font-size: 9px;
  font-weight: 800;

  text-align: center;

  text-transform: uppercase;
}


/* grilla */
.rep-date-dialog .rep-calendar-grid {
  display: grid;

  grid-template-columns: repeat(7, 1fr);

  gap: 4px;
}


/* días */
.rep-date-dialog .rep-calendar-grid button {
  min-width: 0;

  height: 36px;

  padding: 0;

  border-radius: 10px;

  border: 1px solid transparent;

  background: transparent;

  color: rgba(255,255,255,0.72);

  font-family: inherit;

  font-size: 12px;
  font-weight: 750;

  cursor: pointer;

  transition:
    background .13s,
    border-color .13s,
    color .13s,
    transform .13s;
}


.rep-date-dialog .rep-calendar-grid button:hover {
  background: rgba(255,255,255,0.07);

  color: #fff;
}


/* días fuera del mes */
.rep-date-dialog .rep-calendar-grid button.other-month {
  color: rgba(255,255,255,0.16);
}


/* día actual */
.rep-date-dialog .rep-calendar-grid button.today {
  border-color: rgba(255,255,255,0.20);
}


/* día seleccionado */
.rep-date-dialog .rep-calendar-grid button.selected {
  background: #fff;

  border-color: #fff;

  color: #111;

  font-weight: 900;

  box-shadow:
    0 5px 14px rgba(0,0,0,0.26);
}


/* rango por compatibilidad */
.rep-date-dialog .rep-calendar-grid button.in-range {
  background: rgba(255,255,255,0.10);

  color: #fff;
}


/* =========================================================
   PIE DEL CALENDARIO
   ========================================================= */

.rep-date-dialog .rep-date-footer {
  width: 100%;

  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 12px;

  margin-top: 12px;

  color: rgba(255,255,255,0.42);

  font-size: 11px;
  font-weight: 650;

  line-height: 1.3;
}


.rep-date-dialog .rep-date-clear {
  flex-shrink: 0;

  padding: 4px 0;

  border: 0;

  background: transparent;

  color: rgba(255,255,255,0.55);

  font-family: inherit;

  font-size: 11px;
  font-weight: 750;

  cursor: pointer;
}


.rep-date-dialog .rep-date-clear:hover {
  color: #fff;
}


/* =========================================================
   CONTINUAR
   ========================================================= */

.rep-date-dialog .rep-date-apply {
  width: 100%;

  height: 46px;

  margin-top: 16px;

  padding: 0 16px;

  border: 1px solid rgba(255,255,255,0.24);

  border-radius: 14px;

  background:
    linear-gradient(
      180deg,
      #ffffff 0%,
      #dedede 56%,
      #c4c4c4 100%
    );

  color: #111;

  font-family: inherit;

  font-size: 12px;
  font-weight: 900;

  letter-spacing: .06em;

  cursor: pointer;

  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    0 7px 20px rgba(0,0,0,0.30);

  transition:
    transform .15s,
    filter .15s;
}


.rep-date-dialog .rep-date-apply:hover {
  transform: translateY(-1px);

  filter: brightness(1.04);
}


.rep-date-dialog .rep-date-apply:active {
  transform: scale(.985);
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 520px) {

  .rep-flow-modal {
    padding: 12px;
  }


  .rep-flow-panel {
    width: min(94vw, 380px);

    padding: 18px;

    border-radius: 22px;
  }


  .rep-flow-title {
    font-size: 17px;
  }


  .rep-date-dialog .rep-calendar {
    padding: 11px;
  }


  .rep-date-dialog .rep-calendar-grid button {
    height: 38px;
  }

}
/* =========================================================
   REPORTES — MINI MODAL DE CAJA
   ========================================================= */

#rep-caja-modal {
  z-index: 9850;
}


/* panel */
#rep-caja-modal .rep-caja-panel {
  width: min(390px, 94vw);
}


/* contenedor de opciones */
.rep-caja-options {
  display: flex;
  flex-direction: column;

  gap: 10px;

  margin-top: 2px;
}


/* botón base */
.rep-caja-option {
  width: 100%;

  min-height: 54px;

  padding: 0 16px;

  border-radius: 15px;

  border: 1px solid rgba(255,255,255,0.10);

  background: rgba(255,255,255,0.045);

  color: rgba(255,255,255,0.78);

  font-family: inherit;

  font-size: 12px;
  font-weight: 850;

  letter-spacing: .05em;

  cursor: pointer;

  display: flex;
  align-items: center;
  justify-content: center;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.06);

  transition:
    transform .15s ease,
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    box-shadow .15s ease;
}


/* hover */
.rep-caja-option:hover {
  transform: translateY(-1px);

  background: rgba(255,255,255,0.09);

  border-color: rgba(255,255,255,0.20);

  color: #fff;
}


/* click */
.rep-caja-option:active {
  transform: scale(.985);
}


/* todas las cajas */
.rep-caja-all {
  min-height: 58px;

  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,0.11) 0%,
      rgba(255,255,255,0.055) 100%
    );

  border-color: rgba(255,255,255,0.16);

  color: #fff;
}


/* grid cajas 1 - 5 */
.rep-caja-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0,1fr));

  gap: 10px;
}


/* Caja 5 ocupa todo el ancho */
.rep-caja-last {
  grid-column: 1 / -1;
}


/* estado seleccionado por si luego queremos mostrarlo */
.rep-caja-option.active {
  background: #fff;

  border-color: #fff;

  color: #111;

  box-shadow:
    0 2px 0 rgba(255,255,255,0.80) inset,
    0 8px 20px rgba(0,0,0,0.26);
}


/* móvil */
@media (max-width: 520px) {

  #rep-caja-modal .rep-caja-panel {
    width: min(94vw, 380px);
  }


  .rep-caja-option {
    min-height: 52px;
  }


  .rep-caja-all {
    min-height: 56px;
  }

}
/* =========================================================
   REPORTES — SELECTOR VERTICAL PREMIUM
   ========================================================= */

/* Panel principal */
#reportes-modal .rep-panel {
  width: min(560px, 94vw) !important;
  padding: 30px 32px 26px !important;
}


/* Header */
.rep-main-head {
  margin-bottom: 30px !important;
}

.rep-main-title {
  font-size: 20px !important;
  font-weight: 900 !important;
  letter-spacing: .10em !important;
}


/* =========================================================
   OPCIONES VERTICALES
   ========================================================= */

.rep-main-options {
  display: flex !important;
  flex-direction: column !important;

  gap: 0 !important;

  width: 100%;
}


/* Cada opción deja de parecer una card */
.rep-main-option {
  position: relative;

  width: 100% !important;
  height: 78px !important;
  min-height: 78px !important;

  padding: 0 48px 0 4px !important;

  border: 0 !important;
  border-bottom: 1px solid rgba(255,255,255,0.09) !important;

  border-radius: 0 !important;

  background: transparent !important;

  box-shadow: none !important;

  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;

  text-align: left !important;

  color: rgba(255,255,255,0.62) !important;

  cursor: pointer;

  transition:
    color .18s ease,
    padding-left .18s ease,
    background .18s ease !important;
}


/* La última no necesita línea inferior */
.rep-main-option:last-child {
  border-bottom: 0 !important;
}


/* Nombre */
.rep-main-option-title {
  font-size: 15px !important;
  font-weight: 850 !important;

  letter-spacing: .055em !important;

  white-space: nowrap;
}


/* =========================================================
   FLECHA
   Reutilizamos el span que antes mostraba el check
   ========================================================= */

.rep-main-option-check {
  position: absolute !important;

  top: 50% !important;
  right: 6px !important;

  width: auto !important;
  height: auto !important;

  transform: translateY(-50%);

  border: 0 !important;
  border-radius: 0 !important;

  background: transparent !important;

  color: transparent !important;

  font-size: 0 !important;

  transition:
    transform .18s ease,
    color .18s ease !important;
}


/* Creamos la flecha */
.rep-main-option-check::after {
  content: '›';

  color: rgba(255,255,255,0.28);

  font-size: 28px;
  font-weight: 300;

  line-height: 1;

  transition:
    color .18s ease,
    transform .18s ease;
}


/* =========================================================
   HOVER
   ========================================================= */

.rep-main-option:hover {
  transform: none !important;

  padding-left: 12px !important;

  background:
    linear-gradient(
      90deg,
      rgba(255,255,255,0.055),
      transparent 72%
    ) !important;

  color: #fff !important;
}


.rep-main-option:hover .rep-main-option-check::after {
  color: #fff;

  transform: translateX(4px);
}


/* =========================================================
   SELECCIONADO
   ========================================================= */

.rep-main-option.active {
  background:
    linear-gradient(
      90deg,
      rgba(255,255,255,0.075),
      transparent 72%
    ) !important;

  color: #fff !important;

  box-shadow: none !important;
}


.rep-main-option.active .rep-main-option-check {
  background: transparent !important;
  color: transparent !important;
}


.rep-main-option.active .rep-main-option-check::after {
  color: rgba(255,255,255,0.85);
}


/* pequeña línea blanca a la izquierda */
.rep-main-option.active::before {
  content: '';

  position: absolute;

  left: -12px;
  top: 50%;

  width: 2px;
  height: 26px;

  border-radius: 10px;

  background: rgba(255,255,255,0.85);

  transform: translateY(-50%);
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 600px) {

  #reportes-modal .rep-panel {
    width: min(94vw, 440px) !important;

    padding: 24px 22px 20px !important;
  }


  .rep-main-head {
    margin-bottom: 20px !important;
  }


  .rep-main-option {
    height: 68px !important;
    min-height: 68px !important;

    padding:
      0 42px 0 4px !important;
  }


  .rep-main-option:hover {
    padding-left: 9px !important;
  }


  .rep-main-option-title {
    font-size: 13px !important;
  }


  .rep-main-option-check {
    right: 4px !important;
  }


  .rep-main-option-check::after {
    font-size: 25px;
  }

}*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --glass-border:  rgba(255,200,120,0.01);
  --glass-shine:   rgba(255,200,140,0.12);
  --text-primary:  rgba(238,234,252,0.96);
  --text-secondary:rgba(210,190,170,0.78);
  --text-dim:      rgba(180,160,135,0.50);
  --accent: #d4af37;
  --accent-bright: #f5d76e;
  --accent-glow:   rgba(230,130,40,0.38);
}

  html, body {
    height: 100%; overflow: hidden;
    -webkit-text-size-adjust: 100%;
    touch-action: manipulation;
    font-family: -apple-system,'SF Pro Display','Helvetica Neue',Arial,sans-serif;
    background:
      radial-gradient(ellipse 80% 60% at 15% 10%, rgba(255,255,255,0.07) 0%, transparent 60%),
      radial-gradient(ellipse 70% 50% at 85% 90%, rgba(255,255,255,0.05) 0%, transparent 55%),
      radial-gradient(ellipse 50% 40% at 50% 50%, rgba(60,60,60,0.18) 0%, transparent 70%),
      linear-gradient(160deg, #000000 0%, #111111 40%, #0a0a0a 70%, #000000 100%);
    color: var(--text-primary);
  }

  body::before { display: none; }
  body::after  { display: none; }

  /* Figuras geométricas del fondo */
  .bg-shape { position: fixed; pointer-events: none; z-index: 0; }

  /* ── Círculos — esquina superior izquierda ── */
  .bg-c1 {
    width: 560px; height: 560px;
    border: 10px solid rgba(255,255,255,0.10); border-radius: 50%;
    top: -180px; left: -180px;
  }
  .bg-c2 {
    width: 360px; height: 360px;
    border: 7px solid rgba(255,255,255,0.07); border-radius: 50%;
    top: -90px; left: -90px;
  }
  /* ── Esquina inferior derecha ── */
  .bg-c3 {
    width: 500px; height: 500px;
    border: 10px solid rgba(255,255,255,0.09); border-radius: 50%;
    bottom: -160px; right: -160px;
  }
  .bg-c4 {
    width: 300px; height: 300px;
    border: 7px solid rgba(255,255,255,0.06); border-radius: 50%;
    bottom: -70px; right: -70px;
  }
  /* ── Círculos concéntricos centrales ── */
  .bg-c5 {
    width: 620px; height: 620px;
    border: 1.5px solid rgba(255,255,255,0.06); border-radius: 50%;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
  }
  .bg-c6 {
    width: 420px; height: 420px;
    border: 1.5px solid rgba(255,255,255,0.04); border-radius: 50%;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
  }
  /* ── Círculo superior derecho ── */
  .bg-c7 {
    width: 220px; height: 220px;
    border: 6px solid rgba(255,255,255,0.08); border-radius: 50%;
    top: 8%; right: 8%;
  }
  .bg-c8 {
    width: 130px; height: 130px;
    border: 5px solid rgba(255,255,255,0.14); border-radius: 50%;
    top: 14%; right: 13%;
  }
  /* ── Círculo inferior izquierdo ── */
  .bg-c9 {
    width: 180px; height: 180px;
    border: 6px solid rgba(255,255,255,0.07); border-radius: 50%;
    bottom: 12%; left: 6%;
  }
  /* ── Círculo extra — lado derecho medio ── */
  .bg-c10 {
    width: 110px; height: 110px;
    border: 5px solid rgba(255,255,255,0.12); border-radius: 50%;
    top: 45%; right: 4%;
  }
  /* ── Cuadrado rotado — centro-izquierda ── */
  .bg-sq {
    width: 190px; height: 190px;
    border: 5px solid rgba(255,255,255,0.05);
    transform: rotate(45deg);
    top: 55%; left: 5%;
  }
  /* ── Triángulo — arriba centro ── */
  .bg-tri {
    width: 0; height: 0;
    border-left: 90px solid transparent;
    border-right: 90px solid transparent;
    border-bottom: 155px solid rgba(255,255,255,0.04);
    top: 6%; left: 42%;
  }

  /* Blobs ocultos */
  .blob, .blob4 { display: none; }
  .glass {
    background: rgba(255,255,255,0.05);

    backdrop-filter: blur(30px) saturate(180%);
    -webkit-backdrop-filter: blur(30px) saturate(180%);

    border: 1px solid rgba(255,255,255,0.18);

    box-shadow:
      0 8px 32px rgba(0,0,0,0.15),
      inset 0 1px 1px rgba(255,255,255,0.3);

    border-radius: 22px;
  }

#app {
  position: relative; z-index:1;
  display: grid;
  grid-template-rows: 74px 1fr;
  /* Productos reciben al menos 60% del ancho, panel de órdenes max 38% */
  /* Layout fijo para tablet: catálogo a la izquierda y pedido a la derecha */
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-areas:
    "topbar topbar"
    "products order";
  height: 100dvh;
  gap: 8px;
  padding: 10px;
}

/* ── TOP BAR: search icon + user badge ── */
#top-bar {
  grid-area: topbar;
  display: flex;
  align-items: center;
  gap: 24px;
}

/* ── Search bar: compact 3D square that expands on focus ── */
#search-bar {
  width: 56px; height: 56px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  border-radius: 18px;
  overflow: hidden;
  transition: width 0.30s cubic-bezier(.4,0,.2,1);
  background: linear-gradient(180deg,#ffffff 0%,#d0d0d0 55%,#b8b8b8 100%);
  border: 1.5px solid rgba(255,255,255,0.92);
  box-shadow:
    0 2px 0 rgba(255,255,255,0.90) inset,
    -1px 0 0 rgba(255,255,255,0.50) inset,
    0 1px 3px rgba(0,0,0,0.20) inset,
    0 8px 24px rgba(0,0,0,0.50),
    0 3px 8px rgba(0,0,0,0.30);
  cursor: pointer;
}
#search-bar:focus-within {
  width: min(380px, 55vw);
}
#search-icon-btn {
  width: 56px; height: 56px; flex-shrink: 0;
  background: transparent; border: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  color: #1a1a1a; padding: 0;
}
#search-icon-btn svg { display: block; }
#search {
  flex: 1; width: 0; opacity: 0;
  background: transparent; border: none; outline: none;
  color: #111; font-size: 16px; font-family: inherit; font-weight: 600;
  padding: 0; min-width: 0;
  transition: opacity 0.22s;
}
#search-bar:focus-within #search {
  width: auto; opacity: 1; padding: 0 12px 0 0;
}
#search::placeholder { color: rgba(0,0,0,0.38); }
#search-clear {
  width: 24px; height: 24px; border-radius: 50%;
  background: rgba(0,0,0,0.12); border: none; color: #333;
  font-size: 11px; font-weight: 900; cursor: pointer; display: none;
  align-items: center; justify-content: center;
  flex-shrink: 0; margin-right: 10px;
}
#search-done {
  display: none;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-height: 32px;
  margin-right: 8px;
  padding: 0 12px;
  border: 1px solid rgba(0,0,0,0.18);
  border-radius: 10px;
  background: rgba(255,255,255,0.72);
  color: #222;
  font: 700 12px/1 inherit;
  cursor: pointer;
  touch-action: manipulation;
}
#search-bar:focus-within #search-done { display: flex; }
#search-done:active { transform: translateY(1px); }

/* ── Top user badge ── */
#top-user {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  border-radius: 16px;
  background: rgba(255,255,255,0.07);
  border: 1px solid rgba(255,255,255,0.14);
  box-shadow: 0 4px 16px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.15);
  backdrop-filter: blur(20px);
  margin-left: auto;
}
#top-user .user-badge-name { font-weight:800; font-size:13px; color:var(--text-primary); }
#top-user .user-badge-caja { color:var(--text-secondary); font-size:11px; margin-top:1px; }

#products-panel {
  grid-area: products;
  /* El panel hace el scroll, no el grid interno */
  overflow-y: auto;
  overflow-x: hidden;
  display: block;
  padding: 4px 4px 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.18) transparent;
}
#products-panel::-webkit-scrollbar { width: 4px; }
#products-panel::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.18); border-radius: 4px; }
#products-panel::before { display: none; }

#product-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  /* Sin height constraint: las filas crecen libremente según aspect-ratio */
  gap: 16px;
  padding: 0 0 96px;
}
#product-grid::-webkit-scrollbar { width: 4px; }
#product-grid::-webkit-scrollbar-thumb { background:rgba(230,115,30,0.36); border-radius:4px; }

.prod-card {
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 18px; cursor: pointer;
  transition: transform .2s cubic-bezier(.34,1.5,.64,1), box-shadow .2s ease, border-color .15s;
  box-shadow: 0 4px 20px rgba(0,0,0,0.55);
  position: relative; overflow: hidden;
  display: block;
  background: #1a1a1a;
  /* cuadrado perfecto que se adapta al ancho de la columna */
  aspect-ratio: 1 / 1;
}
.prod-card::before { display: none; }
.prod-card:hover { transform: scale(1.025); border-color: rgba(255,255,255,0.38); box-shadow: 0 8px 32px rgba(0,0,0,0.70); }
