}
.sum-card-label { font-size:11px; color:rgba(255,255,255,0.55); font-weight:700; text-transform:uppercase; letter-spacing:.08em; margin-bottom:6px; }
.sum-card-value { font-size:26px; font-weight:900; color:var(--accent-bright); letter-spacing:-.02em; line-height:1; }
.inv-cajas-grid { display:flex; flex-direction:column; gap:14px; overflow-y:auto; max-height:52vh; padding-right:4px; scrollbar-width:thin; scrollbar-color:rgba(230,115,30,0.36) transparent; }
