  box-shadow: 0 6px 24px rgba(0,0,0,0.40), inset 0 1px 0 rgba(255,255,255,0.10);
}
.inv-caja-header { display:flex; align-items:center; justify-content:space-between; margin-bottom:18px; flex-wrap:wrap; gap:10px; }
.inv-caja-name { display:flex; align-items:center; gap:10px; font-size:22px; font-weight:900; color:#fff; letter-spacing:-.02em; }
.inv-caja-badge {
  display:flex; align-items:center; justify-content:center; width:32px; height:32px;
  border-radius:10px; background:linear-gradient(145deg,rgba(230,115,30,.90),rgba(178,63,18,.90));
  color:#fff; font-size:12px; font-weight:900; letter-spacing:.02em;
  box-shadow:0 5px 14px rgba(190,70,20,.24);
}
.inv-caja-cajero { font-size:14px; color:var(--text-secondary); font-weight:600; margin-top:2px; }
.inv-caja-cnt {
  font-size:13px; font-weight:800; padding:5px 14px; border-radius:10px;
  background:rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.16);
  color:rgba(255,255,255,0.75); white-space:nowrap;
}
.inv-caja-methods { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin-bottom:16px; }
.inv-method-item {
  background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.12);
  border-radius:14px; padding:14px 16px;
}
.inv-method-label { font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:rgba(255,255,255,0.50); margin-bottom:8px; }
.inv-method-val { font-size:22px; font-weight:900; color:#fff; letter-spacing:-.02em; }
.inv-caja-total {
  display:flex; justify-content:space-between; align-items:center;
  border-top:1px solid rgba(255,255,255,0.12); padding-top:14px;
}
.inv-caja-total-lbl { font-size:12px; font-weight:800; text-transform:uppercase; letter-spacing:.12em; color:rgba(255,255,255,0.45); }
.inv-caja-total-val { font-size:30px; font-weight:900; color:var(--accent-bright); letter-spacing:-.03em; line-height:1; }
@media (max-width:560px) {
  .summary-cards { grid-template-columns:repeat(2,1fr); gap:10px; }
  .sum-card { padding:15px 14px; }
  .sum-card-value { font-size:21px; }
  .inv-caja-card { padding:18px 16px; }
  .inv-caja-methods { gap:8px; }
  .inv-method-item { padding:12px 10px; }
  .inv-method-val { font-size:17px; }
}
.inv-empty { text-align:center; padding:40px; color:var(--text-dim); font-size:15px; }
.data-table { width:100%; border-collapse:collapse; font-size:13px; }
.data-table th {
  padding:10px 10px; text-align:left; font-size:10px; font-weight:700;
  text-transform:uppercase; letter-spacing:.06em; color:rgba(255,255,255,0.60);
  border-bottom:1px solid rgba(255,255,255,0.18); white-space:nowrap;
}
.data-table td { padding:9px 10px; border-bottom:1px solid rgba(130,105,190,0.14); color:rgba(238,225,210,0.90); vertical-align:middle; }
.data-table tr:last-child td { border-bottom:none; }
.data-table tr:hover td { background:rgba(100,28,40,0.05); }
.status-dot { display:inline-block; width:8px; height:8px; border-radius:50%; margin-right:5px; vertical-align:middle; }
.status-dot.ok   { background:#7dba82; box-shadow:0 0 6px rgba(190,140,75,0.55); }
.status-dot.fail { background:#ff6b6b; box-shadow:0 0 6px rgba(255,100,100,0.5); }
.anular-btn {
  padding:4px 10px; border-radius:7px; border:1px solid rgba(255,100,100,0.3);
  background:rgba(255,80,80,0.1); color:rgba(255,130,130,0.85);
  font-size:11px; font-weight:700; cursor:pointer; font-family:inherit; transition:all .14s;
}
.anular-btn:hover { background:rgba(255,80,80,0.22); }
.anular-btn:disabled { opacity:.35; cursor:not-allowed; }
.export-btn {
  padding:12px 24px; border-radius:14px; border:none;
  background:linear-gradient(135deg,rgba(210,95,20,0.88),rgba(215,105,25,0.88));backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,0.30);
  color:#fff; font-size:14px; font-weight:700; cursor:pointer;
  font-family:inherit; transition:all .15s; box-shadow:0 4px 14px rgba(210,90,20,0.38); margin-top:18px;
}
.export-btn:hover { transform:translateY(-2px); box-shadow:0 8px 24px rgba(230,115,30,0.48); }
.rep-search {
  flex:1; padding:8px 14px; border-radius:10px; border:1px solid rgba(230,115,30,0.36);
  background:rgba(16,12,32,0.84); color:var(--text-primary); font-size:13px;
  outline:none; font-family:inherit;
}

/* Inventarios: panel completamente opaco para que el contenido no se mezcle
   con el POS que queda detrás en tablets y pantallas grandes. */
#inventarios-modal {
  background: #000 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
#inventarios-modal .inv-panel {
  background: #050505 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-color: #252525 !important;
  box-shadow: 0 28px 80px #000 !important;
}
#inventarios-modal .modal-close,
#inventarios-modal .filter-btn,
#inventarios-modal .sum-card,
#inventarios-modal .inv-caja-card,
#inventarios-modal .inv-caja-cnt,
#inventarios-modal .inv-method-item {
  background: #0b0b0b !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
#inventarios-modal .filter-btn.active {
  background: #54200d !important;
}
#inventarios-modal .inv-caja-card {
  border-color: #242424 !important;
}
#inventarios-modal .sum-card,
#inventarios-modal .inv-method-item {
  border-color: #202020 !important;
  box-shadow: none !important;
}
#inventarios-modal .inv-caja-cnt {
  border-color: #252525 !important;
}

/* ========== CAJA MODAL ========== */
#caja-modal {
  display:none; position:fixed; inset:0; z-index:9200;
  align-items:center; justify-content:center;
  background:rgba(5,3,15,0.8); backdrop-filter:blur(14px);
}
#caja-modal.open { display:flex; }
.caja-panel {
  background: rgba(255,255,255,0.07);
  backdrop-filter: blur(48px) saturate(200%);
  -webkit-backdrop-filter: blur(48px) saturate(200%);
  border: 1.5px solid rgba(255,255,255,0.72);
  border-radius: 28px; padding: 36px 32px 30px;
  width: min(600px,94vw); color: #fff;
  box-shadow:
    0 2px 0 0 rgba(255,255,255,0.55) inset,
    0 -1px 0 0 rgba(255,255,255,0.18) inset,
    1px 0 0 0 rgba(255,255,255,0.22) inset,
    -1px 0 0 0 rgba(255,255,255,0.12) inset,
    0 40px 100px rgba(0,0,0,0.75),
    0 0 80px rgba(120,90,210,0.20);
}
.caja-step { display:none; flex-direction:column; gap:16px; }
.caja-step.active { display:flex; }
.caja-step-num {
  font-size:11px; font-weight:700; letter-spacing:.1em; text-transform:uppercase;
  color:var(--text-secondary); margin-bottom:2px;
}
.caja-title { font-size:22px; font-weight:900; letter-spacing:-.01em; }
.caja-sub { font-size:14px; color:var(--text-secondary); }
.caja-name-tag {
  background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.20);
  border-radius:12px; padding:12px 16px; font-size:15px; font-weight:700;
  color:var(--text-primary); text-align:center;
}
.caja-card-horiz {
  display:flex; align-items:center; gap:22px;
  background:rgba(14,10,30,0.88); border:1px solid rgba(255,255,255,0.38);
  border-radius:20px; padding:22px 26px;
}
.caja-abrir-square {
  width:86px; height:86px; border-radius:18px; border:1px solid rgba(255,255,255,0.22); flex-shrink:0;
  background:linear-gradient(145deg,rgba(255,255,255,0.16) 0%,rgba(255,255,255,0.06) 100%);
  color:#fff; font-size:13px; font-weight:800; cursor:pointer;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:5px;
  font-family:inherit; line-height:1.2;
  box-shadow:0 6px 22px rgba(0,0,0,0.45), inset 0 1.5px 0 rgba(255,255,255,0.28);
  transition:transform .12s, box-shadow .12s;
}
.caja-abrir-square:hover { transform:scale(1.05); background:linear-gradient(145deg,rgba(255,255,255,0.24) 0%,rgba(255,255,255,0.10) 100%); box-shadow:0 10px 32px rgba(0,0,0,0.55), inset 0 1.5px 0 rgba(255,255,255,0.35); }
.caja-card-right { flex:1; }
.caja-card-num {
  font-size:52px; font-weight:900; line-height:1; letter-spacing:-.02em;
  color:var(--text-primary);
}
.caja-card-cajera { font-size:15px; color:var(--text-secondary); margin-top:6px; font-weight:600; }
.caja-input-wrap { display:flex; flex-direction:column; gap:6px; }
.caja-input-label { font-size:11px; font-weight:700; color:var(--text-secondary); text-transform:uppercase; letter-spacing:.06em; }
.caja-input {
  width:100%; padding:22px 24px; border-radius:18px;
  border:2px solid rgba(255,255,255,0.70);
  background:linear-gradient(180deg,rgba(255,255,255,0.14) 0%,rgba(255,255,255,0.05) 100%);
  color:#fff; font-size:32px; font-weight:900; outline:none; text-align:center;
  font-family:inherit; transition:all .18s; box-sizing:border-box;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.18) inset,
    0 8px 28px rgba(0,0,0,0.40);
  letter-spacing:0.03em;
}
.caja-input:focus {
  border-color:rgba(255,255,255,0.90);
  background:linear-gradient(180deg,rgba(255,255,255,0.20) 0%,rgba(255,255,255,0.08) 100%);
  box-shadow:
    0 2px 0 rgba(255,255,255,0.25) inset,
    0 12px 36px rgba(0,0,0,0.50),
    0 0 0 3px rgba(255,255,255,0.18);
}
.caja-input.sm { font-size:22px; padding:16px 20px; }
.caja-cierre-row {
  display:grid; grid-template-columns:1fr 1fr; gap:10px;
}
.caja-result-grid {
  background:rgba(12,6,28,0.55); border:1px solid rgba(255,255,255,0.35);
  border-radius:14px; padding:14px 16px; display:flex; flex-direction:column; gap:8px;
}
.caja-result-row { display:flex; justify-content:space-between; align-items:center; font-size:13px; }
.caja-result-row .lbl { color:var(--text-secondary); font-weight:600; }
.caja-result-row .val { font-weight:800; }
.caja-result-row .val.ok    { color:#7dba82; }
.caja-result-row .val.falta { color:#ff6b6b; }
.caja-result-row .val.sobra { color:#f59e0b; }
.caja-result-total {
  border-top:1px solid rgba(255,255,255,0.35); padding-top:8px; margin-top:2px;
  font-size:15px; font-weight:900;
}
.caja-btn-primary {
  width:100%; padding:20px; border-radius:18px; border:none;
  background:linear-gradient(180deg,#ffffff 0%,#d8d8d8 55%,#c0c0c0 100%);
  color:#111; font-size:18px; font-weight:800; cursor:pointer;
  font-family:inherit; transition:all .18s; letter-spacing:0.02em;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.60) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 8px 28px rgba(0,0,0,0.45),
    0 3px 8px rgba(0,0,0,0.25);
}
.caja-btn-primary:hover {
  transform:translateY(-2px);
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.60) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 14px 36px rgba(0,0,0,0.52),
    0 4px 12px rgba(0,0,0,0.30);
}
.caja-btn-primary:active { transform:translateY(1px); }
.caja-btn-primary.green {
  background:linear-gradient(180deg,#6ee87a 0%,#3fcc50 55%,#28b03a 100%);
  color:#fff;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.55) inset,
    0 8px 28px rgba(50,180,70,0.45),
    0 3px 8px rgba(0,0,0,0.25);
}
.caja-btn-primary.red {
  background:linear-gradient(180deg,#f87171 0%,#dc2626 55%,#b91c1c 100%);
  color:#fff;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.40) inset,
    0 8px 28px rgba(200,40,40,0.45),
    0 3px 8px rgba(0,0,0,0.25);
}
.caja-btns { display:flex; gap:12px; }
.caja-btn-sec {
  flex:1; padding:16px; border-radius:16px;
  border:1.5px solid rgba(255,255,255,0.55);
  background:linear-gradient(180deg,rgba(255,255,255,0.18) 0%,rgba(255,255,255,0.08) 100%);
  color:rgba(255,255,255,0.85);
  font-size:15px; font-weight:700; cursor:pointer; font-family:inherit; transition:all .15s;
  box-shadow:
    0 1px 0 rgba(255,255,255,0.25) inset,
    0 4px 12px rgba(0,0,0,0.30);
}
.caja-btn-sec:hover {
  background:linear-gradient(180deg,rgba(255,255,255,0.25) 0%,rgba(255,255,255,0.12) 100%);
  color:#fff; transform:translateY(-1px);
}
.caja-estado-tag {
  display:inline-flex; align-items:center; gap:6px;
  font-size:12px; font-weight:700; padding:4px 12px; border-radius:8px;
}
.caja-estado-tag.abierta { background:rgba(100,155,105,0.14); color:#7dba82; border:1px solid rgba(165,80,50,0.42); }
.caja-estado-tag.cerrada { background:rgba(255,100,100,0.1); color:#ff6b6b; border:1px solid rgba(255,100,100,0.25); }

/* ========== MONITOR DE CAJAS ========== */
.caja-panel { overflow-y:auto; max-height:92dvh; }
.monitor-list-wrap { flex:1; overflow-y:auto; display:flex; flex-direction:column; gap:8px; max-height:300px; }
.monitor-card {
  background:rgba(14,10,30,0.88); border:1px solid rgba(255,255,255,0.35);
  border-radius:14px; padding:12px 14px;
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  flex-shrink:0;
}
.monitor-card-caja { font-size:15px; font-weight:800; color:var(--text-primary); }
.monitor-card-meta { font-size:12px; color:var(--text-secondary); margin-top:2px; }
.monitor-card-ap   { font-size:11px; color:var(--text-dim); margin-top:1px; }
.monitor-card-btn  {
  padding:8px 14px; border-radius:10px; border:none;
  background:linear-gradient(135deg,rgba(210,95,20,0.88),rgba(215,105,25,0.88));
  color:#fff; font-size:12px; font-weight:700; cursor:pointer; white-space:nowrap; font-family:inherit;
  transition:opacity .14s;
}
.monitor-card-btn:hover { opacity:.82; }
.monitor-card-badge {
  font-size:11px; font-weight:700; padding:4px 10px; border-radius:8px;
  background:rgba(100,155,105,0.14); color:#7dba82; border:1px solid rgba(165,80,50,0.42);
}
.monitor-open-btn {
  width:100%; padding:11px; border-radius:12px;
  border:1px solid rgba(230,115,30,0.42); background:rgba(80,55,155,0.14);
  color:var(--text-secondary); font-size:13px; font-weight:700;
  cursor:pointer; font-family:inherit; transition:all .14s; margin-top:4px;
}
.monitor-open-btn:hover { background:rgba(80,55,155,0.26); color:var(--text-primary); }

/* ========== CONFIRM TOAST ========== */
#confirm-toast {
  position:fixed; bottom:108px; left:50%; transform:translateX(-50%) translateY(20px);
  z-index:99999; pointer-events:none; opacity:0;
  transition:opacity .22s ease, transform .22s cubic-bezier(.34,1.4,.64,1);
  min-width:300px; max-width:90vw;
}
#confirm-toast.show {
  opacity:1; transform:translateX(-50%) translateY(0); pointer-events:all;
}
.ct-inner {
  background:linear-gradient(160deg,rgba(28,8,14,0.99),rgba(18,4,8,0.99));
  border:1px solid rgba(165,80,50,0.42); border-radius:22px;
  padding:20px 22px 16px;
  box-shadow:0 24px 72px rgba(0,0,0,0.85), 0 0 0 1px rgba(130,105,190,0.06),
    inset 0 1.5px 0 rgba(145,188,148,0.16);
  display:flex; flex-direction:column; gap:14px;
}
.ct-msg {
  font-size:15px; font-weight:700; color:var(--text-primary);
  text-align:center; line-height:1.4;
}
.ct-icon { font-size:24px; text-align:center; margin-bottom:-4px; }
.ct-btns { display:flex; gap:9px; }
.ct-btn {
  flex:1; padding:12px 10px; border-radius:13px; border:none;
  font-size:14px; font-weight:700; cursor:pointer; font-family:inherit;
  transition:all .14s; letter-spacing:.01em;
}
.ct-btn.cancel {
  background:rgba(16,12,32,0.84); border:1.5px solid rgba(255,255,255,0.35);
  color:var(--text-secondary);
}
.ct-btn.cancel:hover { background:rgba(14,10,30,0.86); color:var(--text-primary); }
.ct-btn.danger {
  background:linear-gradient(135deg,rgba(220,60,60,.9),rgba(180,30,30,.9));
  color:#fff; box-shadow:0 4px 16px rgba(200,40,40,0.35);
}
.ct-btn.danger:hover { transform:translateY(-1px); box-shadow:0 8px 24px rgba(200,40,40,0.5); }
.ct-btn.warn {
  background:linear-gradient(135deg,rgba(240,140,30,.9),rgba(200,100,10,.9));
  color:#fff; box-shadow:0 4px 16px rgba(220,120,20,0.35);
}
.ct-btn.warn:hover { transform:translateY(-1px); box-shadow:0 8px 24px rgba(220,120,20,0.5); }

/* ========== ORDENES MODAL ========== */
#ordenes-modal {
  display:none; position:fixed; inset:0; z-index:9300;
  align-items:flex-start; justify-content:center;
  background:rgba(5,3,15,0.86); backdrop-filter:blur(16px);
  padding:24px 16px 24px; overflow-y:auto;
}
#ordenes-modal.open { display:flex; }
.ord-panel {
  background: rgba(255,255,255,0.07);
  backdrop-filter: blur(48px) saturate(200%);
  -webkit-backdrop-filter: blur(48px) saturate(200%);
  border: 1.5px solid rgba(255,255,255,0.72);
  border-radius: 28px; color: #fff;
  padding: 32px 28px 28px; width: min(820px,96vw);
  box-shadow:
    0 2px 0 0 rgba(255,255,255,0.55) inset,
    0 -1px 0 0 rgba(255,255,255,0.18) inset,
    1px 0 0 0 rgba(255,255,255,0.22) inset,
    -1px 0 0 0 rgba(255,255,255,0.12) inset,
    0 40px 120px rgba(0,0,0,0.78),
    0 0 80px rgba(120,90,210,0.18);
}
.ord-search-wrap {
  position:relative; flex:1; min-width:180px;
}
.ord-search-wrap svg {
  position:absolute; left:14px; top:50%; transform:translateY(-50%);
  opacity:.4; pointer-events:none;
}
.ord-search {
  width:100%; padding:12px 14px 12px 40px; border-radius:14px;
  border:1.5px solid rgba(255,255,255,0.35);
  background:rgba(16,12,32,0.84); color:var(--text-primary);
  font-size:14px; outline:none; font-family:inherit; transition:border-color .15s;
  box-sizing:border-box;
}
.ord-search:focus { border-color:rgba(230,115,30,0.60); background:rgba(14,10,30,0.88); }
.ord-search::placeholder { color:var(--text-dim); }

.ord-list {
  display:flex; flex-direction:column; gap:12px;
  max-height:62vh; overflow-y:auto; padding-right:4px;
  scrollbar-width:thin; scrollbar-color:rgba(230,115,30,0.36) transparent;
}
.ord-list::-webkit-scrollbar { width:4px; }
.ord-list::-webkit-scrollbar-thumb { background:rgba(230,115,30,0.36); border-radius:4px; }

.ord-card {
  background:rgba(4,35,24,0.6);
  border:1px solid rgba(255,255,255,0.35);
  border-radius:20px; padding:20px 22px;
  display:grid; grid-template-columns:1fr auto;
  gap:14px; align-items:start;
  box-shadow:0 4px 20px rgba(0,0,0,0.4),
    inset 0 1.5px 0 rgba(145,188,148,0.08);
  transition: border-color .15s;
}
.ord-card:hover { border-color:rgba(165,80,50,0.42); }
.ord-card.anulada {
  opacity:.5; border-color:rgba(255,100,100,0.2);
  background:rgba(255,80,80,0.04);
}
.ord-left { display:flex; flex-direction:column; gap:10px; }
.ord-top { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
.ord-num {
  font-size:22px; font-weight:900; letter-spacing:-.02em;
  background:linear-gradient(135deg,#8c2e20,#6e1e14,#7a2518);
  -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text;
}
.ord-estado-badge {
  display:inline-flex; align-items:center; gap:5px;
  font-size:11px; font-weight:700; padding:4px 11px; border-radius:8px;
}
.ord-estado-badge.ok    { background:rgba(100,155,105,0.14); color:#7dba82; border:1px solid rgba(165,80,50,0.42); }
.ord-estado-badge.fail  { background:rgba(255,100,100,0.12); color:#ff6b6b; border:1px solid rgba(255,100,100,0.25); }
.ord-hora-caja {
  font-size:12px; color:var(--text-secondary); font-weight:600;
  margin-left:auto;
}
.ord-meta { font-size:12px; color:var(--text-secondary); }
.ord-prods {
  font-size:14px; font-weight:600; color:rgba(238,225,210,0.90);
  line-height:1.5;
}
.ord-total-row {
  display:flex; align-items:center; gap:10px; margin-top:2px;
}
.ord-metodo {
  font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.06em;
  background:rgba(100,28,40,0.14); border:1px solid rgba(255,255,255,0.28);
  padding:3px 10px; border-radius:7px; color:rgba(230,220,210,0.95);
}
.ord-total {
  font-size:20px; font-weight:900; letter-spacing:-.02em;
  color:var(--accent-bright);
}
.ord-right {
  display:flex; flex-direction:column; gap:9px; flex-shrink:0; min-width:130px;
}
.ord-btn {
  width:100%; padding:13px 10px; border-radius:14px; border:none;
  font-size:13px; font-weight:700; cursor:pointer; font-family:inherit;
  transition:all .15s; display:flex; align-items:center; justify-content:center; gap:7px;
  letter-spacing:.01em;
}
.ord-btn.print {
  background:linear-gradient(180deg,#ffffff 0%,#e0e0e0 52%,#c8c8c8 100%);
  border:1px solid rgba(255,255,255,0.90);
  color:#111; font-weight:800;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.58) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 6px 20px rgba(0,0,0,0.45);
}
.ord-btn.print:hover { transform:translateY(-2px); box-shadow:0 2px 0 rgba(255,255,255,0.95) inset,-1px 0 0 rgba(255,255,255,0.58) inset,0 1px 3px rgba(0,0,0,0.18) inset,0 12px 28px rgba(0,0,0,0.52); }
.ord-btn.void {
  background:linear-gradient(180deg,rgba(255,255,255,0.14) 0%,rgba(255,255,255,0.06) 100%);
  border:1.5px solid rgba(255,100,100,0.55);
  color:rgba(255,150,150,1); font-weight:700;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.18), 0 3px 10px rgba(0,0,0,0.28);
}
.ord-btn.void:hover { background:rgba(255,80,80,0.22); border-color:rgba(255,100,100,0.85); color:#fff; }
.ord-btn:disabled { opacity:.3; cursor:not-allowed; transform:none !important; box-shadow:none !important; }


/* Product cards */
.prod-card {
  border: 1px solid rgba(255,255,255,0.15) !important;
  box-shadow: 0 4px 20px rgba(0,0,0,0.55) !important;
  background: #1a1a1a !important;
  aspect-ratio: 1 / 1 !important;
}
.prod-card:hover {
  border-color: rgba(255,255,255,0.32) !important;
  box-shadow: 0 10px 36px rgba(0,0,0,0.72) !important;
}
.prod-card::before { display: none !important; }
.prod-img { background-color: transparent !important; object-fit: cover !important; }

/* Order panel — glass transparente estilo dock */
#order-panel {
  background: rgba(255,255,255,0.035) !important;
  backdrop-filter: blur(60px) saturate(200%) !important;
  -webkit-backdrop-filter: blur(60px) saturate(200%) !important;
  border: 1px solid rgba(255,255,255,0.12) !important;
  border-radius: 28px !important;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.18) inset,
    0 -1px 0 rgba(255,255,255,0.05) inset,
    1px 0 0 rgba(255,255,255,0.08) inset,
    -1px 0 0 rgba(255,255,255,0.05) inset,
    0 24px 80px rgba(0,0,0,0.50) !important;
}
#order-panel::before { background: linear-gradient(90deg,transparent,rgba(255,255,255,0.14) 40%,rgba(255,255,255,0.22) 50%,rgba(255,255,255,0.14) 60%,transparent) !important; }
#order-panel::after  { background: linear-gradient(175deg,rgba(255,255,255,0.04) 0%,transparent 40%) !important; }

/* Search bar */
.glass#products-panel {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
}

/* Order items */
.order-item {
  background: rgba(255,255,255,0.07) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(255,255,255,0.12) !important;
  box-shadow: 0 4px 16px rgba(0,0,0,0.18), inset 0 1px 0 rgba(255,255,255,0.16) !important;
}
.order-item::before { background: linear-gradient(180deg,rgba(255,255,255,0.07) 0%,transparent 100%) !important; }

/* Qty buttons */
.qty-btn {
  background: rgba(255,255,255,0.08) !important;
  border: 1px solid rgba(255,255,255,0.16) !important;
  backdrop-filter: blur(12px) !important;
}
.qty-btn:hover { background: rgba(255,255,255,0.16) !important; border-color: rgba(255,255,255,0.30) !important; }

/* Pedido compacto para tablet: nombre, precio y controles siempre visibles */
.order-item {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  gap: 5px 9px;
  align-items: center;
  padding: 10px 11px;
}
.oi-em {
  grid-column: 1;
  grid-row: 1 / 4;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  font-size: 23px;
}
.oi-em img { border-radius: 10px; }
.oi-info {
  grid-column: 2;
  grid-row: 1;
  width: 100%;
}
.oi-name {
  font-size: 13px;
  line-height: 1.2;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
}
.oi-price-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 5px;
  min-width: 0;
}
.oi-unit {
  font-size: 10px;
  white-space: nowrap;
}
.oi-tot {
  min-width: 0;
  font-size: 13px;
  line-height: 1.1;
  white-space: nowrap;
  text-align: right;
}
.oi-ctrl {
  grid-column: 2;
  grid-row: 2 / 4;
  justify-content: flex-start;
  gap: 5px;
}
.qty-btn {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  font-size: 16px;
}
.oi-qty {
  min-width: 20px;
  font-size: 15px;
}

/* User badge */
.user-badge {
  background: rgba(255,255,255,0.07) !important;
  border: 1px solid rgba(255,255,255,0.14) !important;
  backdrop-filter: blur(16px) !important;
}

/* ---- LOGIN FULL REDESIGN ---- */
#login-overlay {
  background:
    radial-gradient(ellipse 75% 60% at 20% 15%, rgba(255,255,255,0.06) 0%, transparent 55%),
    radial-gradient(ellipse 65% 55% at 80% 85%, rgba(255,255,255,0.04) 0%, transparent 55%),
    radial-gradient(ellipse 50% 45% at 50% 50%, rgba(40,40,40,0.50) 0%, transparent 70%),
    #000000 !important;
}
#login-overlay::before {
  content:'';
  position:absolute; inset:0; pointer-events:none; z-index:0;
  background-image: radial-gradient(rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 26px 26px;
}
.login-panel {
  position:relative; z-index:1;
  background: rgba(255,255,255,0.045) !important;
  backdrop-filter: blur(80px) saturate(140%) !important;
  -webkit-backdrop-filter: blur(80px) saturate(140%) !important;
  border: 1px solid rgba(255,255,255,0.10) !important;
  border-radius: 40px !important;
  padding: 52px 48px 44px !important;
  width: min(440px,94vw) !important;
  overflow: visible;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.22) inset,
    0 -1px 0 rgba(255,255,255,0.05) inset,
    1px 0 0 rgba(255,255,255,0.08) inset,
    -1px 0 0 rgba(255,255,255,0.05) inset,
    0 70px 160px rgba(0,0,0,0.94),
    0 0 110px rgba(40,8,75,0.38) !important;
}
.login-panel::before {
  content:'';
  position:absolute; top:0; left:12%; right:12%; height:1px;
  background: linear-gradient(90deg, transparent, rgba(100,220,160,0.55) 25%, rgba(255,255,255,0.85) 50%, rgba(130,90,255,0.55) 75%, transparent);
  pointer-events:none; border-radius:50%;
}
.login-panel::after {
  content:'';
  position:absolute; top:-70px; right:-70px;
  width:190px; height:190px;
  background: radial-gradient(circle, rgba(50,180,100,0.09) 0%, transparent 70%);
  pointer-events:none; border-radius:50%;
}
.login-badge-icon {
  width:68px; height:68px; border-radius:22px; margin:0 auto 22px;
  background: linear-gradient(145deg, rgba(255,255,255,0.14) 0%, rgba(255,255,255,0.04) 100%);
  border: 1.5px solid rgba(255,255,255,0.18);
  box-shadow: 0 10px 36px rgba(0,0,0,0.55), inset 0 1.5px 0 rgba(255,255,255,0.30), 0 0 40px rgba(60,200,120,0.08);
  display:flex; align-items:center; justify-content:center;
  color:rgba(255,255,255,0.80); position:relative; overflow:hidden;
}
.login-badge-icon::before {
  content:''; position:absolute; inset:0; border-radius:20px;
  background:linear-gradient(145deg, rgba(255,255,255,0.18) 0%, transparent 55%);
  pointer-events:none;
}
.login-logo {
  font-size:26px !important; font-weight:900 !important; letter-spacing:-.03em !important;
  background:linear-gradient(135deg, #ffffff 0%, #d8e8ff 55%, #bccff8 100%) !important;
  -webkit-background-clip:text !important; -webkit-text-fill-color:transparent !important; background-clip:text !important;
  margin-bottom:3px !important;
}
.login-title {
  font-size:13px !important; font-weight:500 !important;
  color:rgba(255,255,255,0.38) !important; margin-bottom:24px !important; letter-spacing:0.03em !important;
}
.login-divider-row {
  display:flex; align-items:center; gap:10px; margin-bottom:22px;
}
.login-divider-line {
  flex:1; height:1px;
  background: linear-gradient(90deg, rgba(255,255,255,0.12), transparent);
}
.login-divider-row .login-divider-line:last-child {
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.12));
}
.login-divider-txt {
  font-size:9.5px; font-weight:800; letter-spacing:.16em;
  color:rgba(255,255,255,0.22); white-space:nowrap;
}
.login-field-wrap {
  position:relative; margin-bottom:12px;
}
.login-field-icon {
  position:absolute; left:17px; top:50%; transform:translateY(-50%);
  color:rgba(255,255,255,0.30); pointer-events:none;
  display:flex; align-items:center;
}
.login-field {
  width:100% !important;
  padding:16px 18px 16px 50px !important;
  border-radius:16px !important;
  border:1px solid rgba(255,255,255,0.09) !important;
  background:rgba(255,255,255,0.055) !important;
  color:var(--text-primary) !important;
  font-size:15px !important; font-weight:600 !important;
  outline:none !important; font-family:inherit !important;
  transition:border-color .18s, background .18s, box-shadow .18s !important;
  box-sizing:border-box !important;
  box-shadow: inset 0 2px 8px rgba(0,0,0,0.22) !important;
}
.login-field:focus {
  background:rgba(255,255,255,0.10) !important;
  border-color:rgba(255,255,255,0.28) !important;
  box-shadow: inset 0 2px 8px rgba(0,0,0,0.22), 0 0 0 3px rgba(255,255,255,0.05) !important;
}
.login-field::placeholder { color:rgba(255,255,255,0.22) !important; }
.login-error {
  font-size:12px !important; color:rgba(255,110,110,0.90) !important; font-weight:600 !important;
  min-height:18px; margin-bottom:10px; text-align:center;
  border-radius:10px; padding:0 12px; transition:padding .15s;
}
.login-error:not(:empty) { padding:8px 12px; background:rgba(255,50,50,0.07); }
.login-btn {
  width:100% !important; padding:17px 22px !important; border-radius:18px !important; border:none !important;
  background:linear-gradient(180deg,#ffffff 0%,#e4e4e4 45%,#cacaca 100%) !important;
  color:#060610 !important; font-size:16px !important; font-weight:800 !important;
  cursor:pointer; font-family:inherit; transition:all .18s; letter-spacing:0.04em;
  display:flex; align-items:center; justify-content:center; gap:10px;
  margin-top:10px; position:relative; overflow:hidden;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.58) inset,
    0 1px 4px rgba(0,0,0,0.20) inset,
    0 10px 36px rgba(0,0,0,0.55),
    0 3px 10px rgba(0,0,0,0.30) !important;
}
.login-btn::before {
  content:''; position:absolute; top:0; left:0; right:0; height:55%;
  background:linear-gradient(180deg, rgba(255,255,255,0.14) 0%, transparent 100%);
  pointer-events:none; border-radius:18px 18px 0 0;
}
.login-btn:hover {
  transform:translateY(-2px) !important;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.58) inset,
    0 1px 4px rgba(0,0,0,0.20) inset,
    0 18px 48px rgba(0,0,0,0.65),
    0 5px 14px rgba(0,0,0,0.36) !important;
}
.login-btn:disabled { opacity:.45; cursor:not-allowed; transform:none !important; }
.login-footer {
  margin-top:20px; font-size:10px; letter-spacing:.08em;
  color:rgba(255,255,255,0.16); text-align:center; text-transform:uppercase; font-weight:600;
}

/* ---- Edit modal ---- */
#edit-modal { background: rgba(4,3,14,0.30) !important; }
.edit-panel {
  background: rgba(255,255,255,0.07) !important;
  backdrop-filter: blur(48px) saturate(200%) !important;
  -webkit-backdrop-filter: blur(48px) saturate(200%) !important;
  border: 1.5px solid rgba(255,255,255,0.72) !important;
  box-shadow:
    0 2px 0 0 rgba(255,255,255,0.55) inset,
    0 -1px 0 0 rgba(255,255,255,0.18) inset,
    1px 0 0 0 rgba(255,255,255,0.22) inset,
    -1px 0 0 0 rgba(255,255,255,0.12) inset,
    0 32px 80px rgba(0,0,0,0.72),
    0 0 60px rgba(120,90,210,0.18) !important;
}
.ep-input {
  background: rgba(255,255,255,0.10) !important;
  border: 1.5px solid rgba(255,255,255,0.35) !important;
  color: #fff !important; font-weight: 600 !important;
}
.ep-input:focus { background: rgba(255,255,255,0.16) !important; border-color: rgba(255,255,255,0.70) !important; }
.ep-btn.cancel {
  background: rgba(255,255,255,0.10) !important;
  border: 1.5px solid rgba(255,255,255,0.35) !important;
  color: rgba(255,255,255,0.85) !important;
  backdrop-filter: blur(12px) !important;
}

/* ---- All modals glass style (matches login panel) ---- */
#inventarios-modal, #reportes-modal, #caja-modal, #edit-modal { background: rgba(4,3,14,0.45) !important; }
.inv-panel, .rep-panel, .caja-panel, .edit-panel {
  background: rgba(255,255,255,0.055) !important;
  backdrop-filter: blur(72px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(72px) saturate(180%) !important;
  border: 1px solid rgba(255,255,255,0.12) !important;
  border-radius: 36px !important;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.20) inset,
    0 -1px 0 rgba(255,255,255,0.06) inset,
    1px 0 0 rgba(255,255,255,0.10) inset,
    -1px 0 0 rgba(255,255,255,0.06) inset,
    0 60px 140px rgba(0,0,0,0.90),
    0 0 80px rgba(100,70,200,0.15) !important;
}

/* Inventarios debe permanecer opaco también frente a las reglas globales de
   modales declaradas arriba. */
#inventarios-modal {
  background: #000 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
#inventarios-modal .inv-panel {
  background: #050505 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-color: #252525 !important;
  box-shadow: 0 28px 80px #000 !important;
}

/* ---- Reportes steps UI ---- */
.rep-step-label { font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.10em; color:var(--text-secondary); margin-bottom:12px; }
.rep-option-btn {
  display:flex; align-items:center; gap:14px;
  width:100%; padding:14px 16px; border-radius:16px; text-align:left;
  background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.12);
  color:#fff; cursor:pointer; font-family:inherit; transition:all .16s;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.09);
}
.rep-option-btn:hover { background:rgba(255,255,255,0.10); border-color:rgba(255,255,255,0.26); transform:translateY(-1px); }
.rep-option-btn.active { background:rgba(230,115,30,0.18); border-color:rgba(230,115,30,0.55); box-shadow:0 0 0 2px rgba(230,115,30,0.18), inset 0 1px 0 rgba(255,255,255,0.12); }
.rep-opt-icon { width:32px; height:32px; flex-shrink:0; display:flex; align-items:center; justify-content:center; }
.rep-opt-icon img { width:28px; height:28px; }
.rep-opt-info { flex:1; min-width:0; }
.rep-opt-title { font-size:15px; font-weight:800; color:#fff; }
.rep-opt-sub { font-size:12px; color:var(--text-secondary); margin-top:2px; line-height:1.3; }
.rep-opt-check {
  font-size:13px; font-weight:900; width:26px; height:26px; border-radius:50%;
  background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.14);
  display:flex; align-items:center; justify-content:center; flex-shrink:0;
  color:transparent; transition:all .15s;
}
.rep-option-btn.active .rep-opt-check { background:rgba(230,115,30,0.40); border-color:rgba(230,115,30,0.70); color:var(--accent-bright); }
.rep-date-trigger {
  display:flex; align-items:center; gap:12px; width:100%; padding:14px 16px;
  border:1px solid rgba(255,255,255,0.16); border-radius:16px;
  background:rgba(255,255,255,0.06); color:#fff; text-align:left;
  cursor:pointer; font-family:inherit; transition:background .15s, border-color .15s, transform .15s;
}
.rep-date-trigger:hover {
  background:rgba(230,115,30,0.14); border-color:rgba(230,115,30,0.52);
  transform:translateY(-1px);
}
.rep-date-trigger-icon {
  display:flex; align-items:center; justify-content:center; width:38px; height:38px;
  border-radius:12px; background:linear-gradient(145deg,rgba(230,115,30,.88),rgba(178,63,18,.88));
  color:#fff; font-size:10px; font-weight:900; letter-spacing:.06em; flex-shrink:0;
}
.rep-date-trigger-copy { display:flex; flex-direction:column; gap:3px; min-width:0; flex:1; }
.rep-date-trigger-copy strong { font-size:14px; font-weight:800; }
.rep-date-trigger-copy span { color:var(--text-secondary); font-size:12px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.rep-date-trigger-arrow { color:var(--accent-bright); font-size:26px; line-height:1; }
.rep-calendar-popover {
  display:none; position:fixed; inset:0; z-index:9800; align-items:center; justify-content:center;
  padding:18px; background:rgba(4,3,14,0.60); backdrop-filter:blur(10px);
}
.rep-calendar-popover.open { display:flex; }
.rep-date-dialog {
  width:min(390px,100%); padding:20px; border-radius:24px;
  background:linear-gradient(160deg,rgba(32,20,48,.98),rgba(15,10,30,.98));
  border:1px solid rgba(255,255,255,.22);
  box-shadow:0 28px 90px rgba(0,0,0,.78), inset 0 1px 0 rgba(255,255,255,.12);
}
.rep-date-dialog-head {
  display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:14px;
}
.rep-date-dialog-head > div { display:flex; flex-direction:column; gap:4px; }
.rep-date-dialog-kicker {
  color:var(--accent-bright); font-size:10px; font-weight:900; letter-spacing:.12em;
}
.rep-date-dialog-head strong { color:#fff; font-size:18px; }
.rep-date-dialog-close { width:34px; height:34px; font-size:14px; }
.rep-calendar {
  width:100%; padding:14px; box-sizing:border-box;
  border:1px solid rgba(255,255,255,0.14); border-radius:18px;
  background:rgba(10,8,28,0.62); box-shadow:inset 0 1px 0 rgba(255,255,255,0.08);
}
.rep-calendar-head {
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  color:#fff; font-size:15px; margin-bottom:12px;
}
.rep-cal-nav {
  width:32px; height:32px; border-radius:10px; border:1px solid rgba(255,255,255,0.16);
  background:rgba(255,255,255,0.08); color:#fff; font-size:22px; line-height:1;
  cursor:pointer; font-family:inherit; transition:background .15s, transform .15s;
}
.rep-cal-nav:hover { background:rgba(230,115,30,0.30); transform:translateY(-1px); }
.rep-cal-weekdays, .rep-calendar-grid {
  display:grid; grid-template-columns:repeat(7,1fr); gap:5px;
}
.rep-cal-weekdays {
  margin-bottom:6px; color:rgba(255,255,255,0.42); font-size:10px;
  font-weight:800; text-align:center; text-transform:uppercase;
}
.rep-calendar-grid button {
  min-height:34px; padding:0; border-radius:9px; border:1px solid transparent;
  background:transparent; color:rgba(255,255,255,0.82); font:700 12px inherit;
  cursor:pointer; transition:background .14s, color .14s, border-color .14s;
}
.rep-calendar-grid button:hover { background:rgba(230,115,30,0.22); color:#fff; }
.rep-calendar-grid button.other-month { color:rgba(255,255,255,0.24); }
.rep-calendar-grid button.today { border-color:rgba(230,115,30,0.62); }
.rep-calendar-grid button.selected,
