  border: none;
  outline: none;
  background: transparent;
}
/* =========================================================
   DESCUENTO DEL PEDIDO
   ========================================================= */

.order-discount-wrap {
  width: 88%;
  margin: 8px auto 10px;

  padding: 9px 11px;

  border-radius: 13px;

  background: rgba(255,255,255,0.028);
  border: 1px solid rgba(255,255,255,0.065);
