  height: 30px;

  padding: 0;

  border: none;
  outline: none;

  background: transparent;
  color: #fff;

  font-family: inherit;
  font-size: 20px;
  font-weight: 900;

  text-align: center;

  box-sizing: border-box;
}

.order-discount-input::placeholder {
  color: rgba(255,255,255,0.20);
}

.order-discount-input:focus {
  border: none;
