#order-panel::before { background: linear-gradient(90deg,transparent,rgba(255,255,255,0.14) 40%,rgba(255,255,255,0.22) 50%,rgba(255,255,255,0.14) 60%,transparent) !important; }
#order-panel::after  { background: linear-gradient(175deg,rgba(255,255,255,0.04) 0%,transparent 40%) !important; }

/* Search bar */
.glass#products-panel {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
}

/* Order items */
.order-item {
  background: rgba(255,255,255,0.07) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(255,255,255,0.12) !important;
  box-shadow: 0 4px 16px rgba(0,0,0,0.18), inset 0 1px 0 rgba(255,255,255,0.16) !important;
}
.order-item::before { background: linear-gradient(180deg,rgba(255,255,255,0.07) 0%,transparent 100%) !important; }

/* Qty buttons */
.qty-btn {
  background: rgba(255,255,255,0.08) !important;
  border: 1px solid rgba(255,255,255,0.16) !important;
  backdrop-filter: blur(12px) !important;
}
.qty-btn:hover { background: rgba(255,255,255,0.16) !important; border-color: rgba(255,255,255,0.30) !important; }

/* Pedido compacto para tablet: nombre, precio y controles siempre visibles */
.order-item {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  gap: 5px 9px;
  align-items: center;
  padding: 10px 11px;
}
.oi-em {
  grid-column: 1;
  grid-row: 1 / 4;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  font-size: 23px;
}
.oi-em img { border-radius: 10px; }
.oi-info {
  grid-column: 2;
  grid-row: 1;
  width: 100%;
}
.oi-name {
  font-size: 13px;
  line-height: 1.2;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
}
.oi-price-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 5px;
  min-width: 0;
}
.oi-unit {
  font-size: 10px;
  white-space: nowrap;
}
.oi-tot {
  min-width: 0;
  font-size: 13px;
  line-height: 1.1;
  white-space: nowrap;
  text-align: right;
}
.oi-ctrl {
  grid-column: 2;
  grid-row: 2 / 4;
  justify-content: flex-start;
  gap: 5px;
}
.qty-btn {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  font-size: 16px;
}
.oi-qty {
  min-width: 20px;
  font-size: 15px;
}

/* User badge */
.user-badge {
  background: rgba(255,255,255,0.07) !important;
  border: 1px solid rgba(255,255,255,0.14) !important;
  backdrop-filter: blur(16px) !important;
}

