/* =========================================================
   NOTA DEL PEDIDO
   ========================================================= */

.order-note-wrap {
  width: 88%;
  margin: 8px auto 10px;

  padding: 9px 11px;

  border-radius: 13px;

  background: rgba(255,255,255,0.028);
  border: 1px solid rgba(255,255,255,0.065);
}

.order-note-label {
  margin-bottom: 4px;

