  text-transform: uppercase;
}

.order-note {
  display: block;

  width: 100%;
  height: 42px;
  min-height: 42px;
  max-height: 42px;

  padding: 7px 8px;

  border: none;
  outline: none;

  resize: none;

  background: transparent;
