/* =========================================================
   REPORTES — MINI MODAL DE FECHA
   ========================================================= */

.rep-flow-modal {
  display: none;

  position: fixed;
  inset: 0;

  z-index: 9800;

  align-items: center;
  justify-content: center;

  padding: 18px;

  background: rgba(0,0,0,0.82);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.rep-flow-modal.open {
  display: flex;
}


/* Panel base de los mini modales */
.rep-flow-panel {
  position: relative;

  width: min(390px, 94vw);

  padding: 22px;

  border-radius: 26px;

  background:
    linear-gradient(
      160deg,
      rgba(28,28,28,0.99) 0%,
      rgba(12,12,12,0.98) 58%,
      rgba(8,8,8,0.99) 100%
    );

  border: 1px solid rgba(255,255,255,0.14);

  box-shadow:
    0 2px 0 rgba(255,255,255,0.16) inset,
    0 -1px 0 rgba(255,255,255,0.04) inset,
    0 28px 80px rgba(0,0,0,0.78);

  color: #fff;

  overflow: hidden;
}


/* brillo superior */
.rep-flow-panel::before {
  content: '';

  position: absolute;

  top: 0;
  left: 14%;
  right: 14%;

  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,255,255,0.22),
      rgba(255,255,255,0.75),
      rgba(255,255,255,0.22),
      transparent
    );

  pointer-events: none;
}


/* =========================================================
   HEADER MINI MODAL
   ========================================================= */

.rep-flow-head {
  display: flex;

  align-items: flex-start;
  justify-content: space-between;

  gap: 14px;

  margin-bottom: 18px;
}


.rep-flow-kicker {
  margin-bottom: 4px;

  color: rgba(255,255,255,0.36);

  font-size: 9px;
  font-weight: 850;

  letter-spacing: .13em;

  text-transform: uppercase;
}


.rep-flow-title {
  color: #fff;

  font-size: 18px;
  font-weight: 900;

  letter-spacing: -.02em;
}


.rep-flow-close {
  width: 34px;
  height: 34px;

  flex-shrink: 0;

  border-radius: 11px;

  border: 1px solid rgba(255,255,255,0.10);

  background: rgba(255,255,255,0.04);

  color: rgba(255,255,255,0.50);

  font-family: inherit;

  font-size: 20px;

  line-height: 1;

  cursor: pointer;

  transition: all .15s;
}


.rep-flow-close:hover {
  background: rgba(255,255,255,0.10);

  border-color: rgba(255,255,255,0.20);

  color: #fff;
}


/* =========================================================
   CALENDARIO
   ========================================================= */

.rep-date-dialog .rep-calendar {
  width: 100%;

  padding: 14px;

  border-radius: 18px;

  border: 1px solid rgba(255,255,255,0.08);

  background: rgba(255,255,255,0.025);

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.05);
}


.rep-date-dialog .rep-calendar-head {
  display: grid;

  grid-template-columns: 36px 1fr 36px;

  align-items: center;

  gap: 8px;

  margin-bottom: 14px;
}


.rep-date-dialog .rep-calendar-head strong {
  text-align: center;

  color: #fff;

  font-size: 14px;
  font-weight: 850;

  text-transform: uppercase;

  letter-spacing: .04em;
}


.rep-date-dialog .rep-cal-nav {
  width: 36px;
  height: 36px;

  border-radius: 11px;

  border: 1px solid rgba(255,255,255,0.09);

  background: rgba(255,255,255,0.04);

  color: rgba(255,255,255,0.68);

  font-family: inherit;

  font-size: 23px;

  line-height: 1;

  cursor: pointer;

  transition: all .15s;
}


.rep-date-dialog .rep-cal-nav:hover {
  background: rgba(255,255,255,0.10);

  color: #fff;

  transform: none;
}


/* días de la semana */
.rep-date-dialog .rep-cal-weekdays {
  display: grid;

  grid-template-columns: repeat(7, 1fr);

  gap: 4px;

  margin-bottom: 6px;

  color: rgba(255,255,255,0.28);

  font-size: 9px;
  font-weight: 800;

  text-align: center;

  text-transform: uppercase;
}


/* grilla */
.rep-date-dialog .rep-calendar-grid {
  display: grid;

  grid-template-columns: repeat(7, 1fr);

  gap: 4px;
}


/* días */
.rep-date-dialog .rep-calendar-grid button {
  min-width: 0;

  height: 36px;

  padding: 0;

  border-radius: 10px;

  border: 1px solid transparent;

  background: transparent;

  color: rgba(255,255,255,0.72);

  font-family: inherit;

  font-size: 12px;
  font-weight: 750;

  cursor: pointer;

  transition:
    background .13s,
    border-color .13s,
    color .13s,
    transform .13s;
}


.rep-date-dialog .rep-calendar-grid button:hover {
  background: rgba(255,255,255,0.07);

  color: #fff;
}


/* días fuera del mes */
.rep-date-dialog .rep-calendar-grid button.other-month {
  color: rgba(255,255,255,0.16);
}


/* día actual */
.rep-date-dialog .rep-calendar-grid button.today {
  border-color: rgba(255,255,255,0.20);
}


/* día seleccionado */
.rep-date-dialog .rep-calendar-grid button.selected {
  background: #fff;

  border-color: #fff;

  color: #111;

  font-weight: 900;

  box-shadow:
    0 5px 14px rgba(0,0,0,0.26);
}


/* rango por compatibilidad */
.rep-date-dialog .rep-calendar-grid button.in-range {
  background: rgba(255,255,255,0.10);

  color: #fff;
}


/* =========================================================
   PIE DEL CALENDARIO
   ========================================================= */

.rep-date-dialog .rep-date-footer {
  width: 100%;

  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 12px;

  margin-top: 12px;

  color: rgba(255,255,255,0.42);

  font-size: 11px;
  font-weight: 650;

  line-height: 1.3;
}


.rep-date-dialog .rep-date-clear {
  flex-shrink: 0;

  padding: 4px 0;

  border: 0;

  background: transparent;

  color: rgba(255,255,255,0.55);

  font-family: inherit;

  font-size: 11px;
  font-weight: 750;

  cursor: pointer;
}


.rep-date-dialog .rep-date-clear:hover {
  color: #fff;
}


/* =========================================================
   CONTINUAR
   ========================================================= */

.rep-date-dialog .rep-date-apply {
  width: 100%;

  height: 46px;

  margin-top: 16px;

  padding: 0 16px;

  border: 1px solid rgba(255,255,255,0.24);

  border-radius: 14px;

  background:
    linear-gradient(
      180deg,
      #ffffff 0%,
      #dedede 56%,
      #c4c4c4 100%
    );

  color: #111;

  font-family: inherit;

  font-size: 12px;
  font-weight: 900;

  letter-spacing: .06em;

  cursor: pointer;

  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    0 7px 20px rgba(0,0,0,0.30);

  transition:
    transform .15s,
    filter .15s;
}


.rep-date-dialog .rep-date-apply:hover {
  transform: translateY(-1px);

  filter: brightness(1.04);
}


.rep-date-dialog .rep-date-apply:active {
  transform: scale(.985);
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 520px) {

  .rep-flow-modal {
    padding: 12px;
  }


  .rep-flow-panel {
    width: min(94vw, 380px);

    padding: 18px;

    border-radius: 22px;
  }


  .rep-flow-title {
    font-size: 17px;
  }


  .rep-date-dialog .rep-calendar {
    padding: 11px;
  }


  .rep-date-dialog .rep-calendar-grid button {
    height: 38px;
  }

}
/* =========================================================
   REPORTES — MINI MODAL DE CAJA
   ========================================================= */

#rep-caja-modal {
  z-index: 9850;
}


/* panel */
#rep-caja-modal .rep-caja-panel {
  width: min(390px, 94vw);
}


/* contenedor de opciones */
.rep-caja-options {
  display: flex;
  flex-direction: column;

  gap: 10px;

  margin-top: 2px;
}


/* botón base */
.rep-caja-option {
  width: 100%;

  min-height: 54px;

  padding: 0 16px;

  border-radius: 15px;

  border: 1px solid rgba(255,255,255,0.10);

  background: rgba(255,255,255,0.045);

  color: rgba(255,255,255,0.78);

  font-family: inherit;

  font-size: 12px;
  font-weight: 850;

  letter-spacing: .05em;

  cursor: pointer;

  display: flex;
  align-items: center;
  justify-content: center;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.06);

  transition:
    transform .15s ease,
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    box-shadow .15s ease;
}


/* hover */
.rep-caja-option:hover {
  transform: translateY(-1px);

  background: rgba(255,255,255,0.09);

  border-color: rgba(255,255,255,0.20);

  color: #fff;
}


/* click */
.rep-caja-option:active {
  transform: scale(.985);
}


/* todas las cajas */
.rep-caja-all {
  min-height: 58px;

  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,0.11) 0%,
      rgba(255,255,255,0.055) 100%
    );

  border-color: rgba(255,255,255,0.16);

  color: #fff;
}


/* grid cajas 1 - 5 */
.rep-caja-grid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0,1fr));

  gap: 10px;
}


/* Caja 5 ocupa todo el ancho */
.rep-caja-last {
  grid-column: 1 / -1;
}


/* estado seleccionado por si luego queremos mostrarlo */
.rep-caja-option.active {
  background: #fff;

  border-color: #fff;

  color: #111;

  box-shadow:
    0 2px 0 rgba(255,255,255,0.80) inset,
    0 8px 20px rgba(0,0,0,0.26);
}


/* móvil */
@media (max-width: 520px) {

  #rep-caja-modal .rep-caja-panel {
    width: min(94vw, 380px);
  }


  .rep-caja-option {
    min-height: 52px;
  }


  .rep-caja-all {
    min-height: 56px;
  }

}
/* =========================================================
   REPORTES — SELECTOR VERTICAL PREMIUM
   ========================================================= */

/* Panel principal */
#reportes-modal .rep-panel {
  width: min(560px, 94vw) !important;
  padding: 30px 32px 26px !important;
}


/* Header */
.rep-main-head {
  margin-bottom: 30px !important;
}

.rep-main-title {
  font-size: 20px !important;
  font-weight: 900 !important;
  letter-spacing: .10em !important;
}


/* =========================================================
   OPCIONES VERTICALES
   ========================================================= */

.rep-main-options {
  display: flex !important;
  flex-direction: column !important;

  gap: 0 !important;

  width: 100%;
}


/* Cada opción deja de parecer una card */
.rep-main-option {
  position: relative;

  width: 100% !important;
  height: 78px !important;
  min-height: 78px !important;

  padding: 0 48px 0 4px !important;

  border: 0 !important;
  border-bottom: 1px solid rgba(255,255,255,0.09) !important;

  border-radius: 0 !important;

  background: transparent !important;

  box-shadow: none !important;

  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;

  text-align: left !important;

  color: rgba(255,255,255,0.62) !important;

  cursor: pointer;

  transition:
    color .18s ease,
    padding-left .18s ease,
    background .18s ease !important;
}


/* La última no necesita línea inferior */
.rep-main-option:last-child {
  border-bottom: 0 !important;
}


/* Nombre */
.rep-main-option-title {
  font-size: 15px !important;
  font-weight: 850 !important;

  letter-spacing: .055em !important;

  white-space: nowrap;
}


/* =========================================================
   FLECHA
   Reutilizamos el span que antes mostraba el check
   ========================================================= */

.rep-main-option-check {
  position: absolute !important;

  top: 50% !important;
  right: 6px !important;

  width: auto !important;
  height: auto !important;

  transform: translateY(-50%);

  border: 0 !important;
  border-radius: 0 !important;

  background: transparent !important;

  color: transparent !important;

  font-size: 0 !important;

  transition:
    transform .18s ease,
    color .18s ease !important;
}


/* Creamos la flecha */
.rep-main-option-check::after {
  content: '›';

  color: rgba(255,255,255,0.28);

  font-size: 28px;
  font-weight: 300;

  line-height: 1;

  transition:
    color .18s ease,
    transform .18s ease;
}


/* =========================================================
   HOVER
   ========================================================= */

.rep-main-option:hover {
  transform: none !important;

  padding-left: 12px !important;

  background:
    linear-gradient(
      90deg,
      rgba(255,255,255,0.055),
      transparent 72%
    ) !important;

  color: #fff !important;
}


.rep-main-option:hover .rep-main-option-check::after {
  color: #fff;

  transform: translateX(4px);
}


/* =========================================================
   SELECCIONADO
   ========================================================= */

.rep-main-option.active {
  background:
    linear-gradient(
      90deg,
      rgba(255,255,255,0.075),
      transparent 72%
    ) !important;

  color: #fff !important;

  box-shadow: none !important;
}


.rep-main-option.active .rep-main-option-check {
  background: transparent !important;
  color: transparent !important;
}


.rep-main-option.active .rep-main-option-check::after {
  color: rgba(255,255,255,0.85);
}


/* pequeña línea blanca a la izquierda */
.rep-main-option.active::before {
  content: '';

  position: absolute;

  left: -12px;
  top: 50%;

  width: 2px;
  height: 26px;

  border-radius: 10px;

  background: rgba(255,255,255,0.85);

  transform: translateY(-50%);
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 600px) {

  #reportes-modal .rep-panel {
    width: min(94vw, 440px) !important;

    padding: 24px 22px 20px !important;
