/* =========================================================
   REPORTES — NUEVO DISEÑO
   ========================================================= */

/* Fondo del modal principal */
#reportes-modal {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 9100;

  align-items: center;
  justify-content: center;

  padding: 20px;

  background: rgba(0,0,0,0.78) !important;

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

#reportes-modal.open {
  display: flex;
}


/* Panel principal — mismo lenguaje visual del login */
#reportes-modal .rep-panel {
  position: relative;

  width: min(720px, 94vw) !important;

  padding: 28px;

  border-radius: 30px !important;

  background:
    linear-gradient(
      160deg,
      rgba(28,28,28,0.98) 0%,
      rgba(12,12,12,0.97) 55%,
      rgba(8,8,8,0.99) 100%
    ) !important;

  backdrop-filter: blur(80px) saturate(140%) !important;
  -webkit-backdrop-filter: blur(80px) saturate(140%) !important;

  border: 1px solid rgba(255,255,255,0.14) !important;

  box-shadow:
    0 2px 0 rgba(255,255,255,0.18) inset,
    0 -1px 0 rgba(255,255,255,0.04) inset,
    0 28px 80px rgba(0,0,0,0.72) !important;

  color: #fff;
}


/* brillo superior */
#reportes-modal .rep-panel::before {
  content: '';

  position: absolute;

  top: 0;
  left: 12%;
  right: 12%;

  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,255,255,0.30),
      rgba(255,255,255,0.80),
      rgba(255,255,255,0.30),
      transparent
    );

  pointer-events: none;
}


/* =========================================================
   HEADER
   ========================================================= */

.rep-main-head {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 26px;
}


.rep-main-title {
  font-size: 21px;
  font-weight: 900;

  letter-spacing: .08em;

  color: #fff;
}


.rep-main-close {
  width: 38px;
  height: 38px;

  border-radius: 12px;

  border: 1px solid rgba(255,255,255,0.10);

  background: rgba(255,255,255,0.045);

  color: rgba(255,255,255,0.55);

  font-family: inherit;
  font-size: 22px;
  font-weight: 500;

  line-height: 1;

  cursor: pointer;

  transition: all .15s;
}


.rep-main-close:hover {
  background: rgba(255,255,255,0.10);
  border-color: rgba(255,255,255,0.20);

  color: #fff;
}


/* =========================================================
   OPCIONES
   ========================================================= */

.rep-main-options {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 12px;
}


.rep-main-option {
  position: relative;

  min-width: 0;

  height: 108px;

  padding: 18px 14px;

  border-radius: 18px;

  border: 1px solid rgba(255,255,255,0.10);

  background: rgba(255,255,255,0.045);

  color: rgba(255,255,255,0.60);

  font-family: inherit;

  cursor: pointer;

  display: flex;
  align-items: center;
  justify-content: center;

  text-align: center;

  transition:
    transform .15s ease,
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    box-shadow .15s ease;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.07);
}


.rep-main-option:hover {
  transform: translateY(-2px);

  background: rgba(255,255,255,0.08);

  border-color: rgba(255,255,255,0.20);

  color: #fff;
}


.rep-main-option.active {
  background: rgba(255,255,255,0.14);

  border-color: rgba(255,255,255,0.34);

  color: #fff;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.26),
    0 10px 28px rgba(0,0,0,0.24);
}


.rep-main-option-title {
  font-size: 14px;
  font-weight: 850;

  letter-spacing: .05em;

  white-space: nowrap;
}


.rep-main-option-check {
  position: absolute;

  top: 10px;
  right: 10px;

  width: 22px;
  height: 22px;

  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  background: rgba(255,255,255,0.08);

  border: 1px solid rgba(255,255,255,0.10);

  color: transparent;

  font-size: 11px;
  font-weight: 900;

  transition: all .15s;
}


.rep-main-option.active .rep-main-option-check {
  background: #fff;

  border-color: #fff;

  color: #111;
}


