/* =========================================================
   CHECKOUT — MISMO LENGUAJE VISUAL DEL LOGIN
   ========================================================= */

#checkout-modal {
  display: none;
  position: fixed;
  top: var(--checkout-viewport-top, 0px);
  right: 0;
  left: 0;
  height: var(--checkout-viewport-height, 100dvh);
  min-height: 0;
  bottom: auto;
  z-index: 9000;

  align-items: flex-start;
  justify-content: center;

  padding: max(8px, env(safe-area-inset-top, 0px)) 18px 12px;

  background: rgba(0,0,0,0.12);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

#checkout-modal.open {
  display: flex;
}


/* PANEL — MISMO ESTILO QUE LOGIN */
.co-panel {
  position: relative;
  z-index: 1;

  width: min(440px, 94vw);
  max-height: min(94dvh, calc(var(--checkout-viewport-height, 100dvh) - 36px));

  overflow-y: auto;
  overflow-x: hidden;

  padding: 28px 26px 24px;

  border-radius: 32px;

  background:
  linear-gradient(
    160deg,
    rgba(28,28,28,0.96) 0%,
    rgba(12,12,12,0.94) 55%,
    rgba(8,8,8,0.97) 100%
  );

  backdrop-filter:
    blur(80px)
    saturate(140%);

  -webkit-backdrop-filter:
    blur(80px)
    saturate(140%);

  border: 1px solid rgba(255,255,255,0.14);
  box-shadow:
  0 2px 0 rgba(255,255,255,0.18) inset,
  0 -1px 0 rgba(255,255,255,0.04) inset,
  0 28px 80px rgba(0,0,0,0.72);
  text-align: center;
  color: #fff;
  scroll-padding-block: 14px;
}

/*
 * En Android, el teclado puede reducir el visual viewport sin cambiar el
 * layout viewport. El modal usa esas variables para centrarse en el espacio
 * realmente visible y evitar que el botón de confirmación quede bajo el IME.
 */
#checkout-modal.keyboard-open {
  align-items: flex-start;
  padding-top: max(8px, calc(var(--checkout-viewport-top, 0px) + 8px));
  padding-bottom: 10px;
}

#checkout-modal.keyboard-open .co-panel {
  max-height: calc(var(--checkout-viewport-height, 100dvh) - 20px);
}
/* brillo superior igual al login */
.co-panel::before {
  content: '';

  position: absolute;

  top: 0;
  left: 12%;
  right: 12%;

  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,255,255,0.30),
      rgba(255,255,255,0.80),
      rgba(255,255,255,0.30),
      transparent
    );

  pointer-events: none;
}


/* ICONO */
.co-icon {
  width: 48px;
  height: 48px;

  margin: 0 auto 10px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 16px;

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,0.14),
      rgba(255,255,255,0.04)
    );

  border:
    1px solid rgba(255,255,255,0.15);

  color:
    rgba(255,255,255,0.80) !important;

  box-shadow:
    0 8px 26px rgba(0,0,0,0.40),
    inset 0 1px 0 rgba(255,255,255,0.25);
}

.co-icon svg {
  width: 24px !important;
  height: 24px !important;
}


/* TITULO */
.co-title {
  font-size: 21px;
  font-weight: 900;

  letter-spacing: -.025em;

  color: #fff;

  margin-bottom: 2px;
}

.co-sub {
  font-size: 12px;
  font-weight: 500;

  color:
    rgba(255,255,255,0.38);

  margin-bottom: 16px;
}


/* =========================================================
   METODOS
   ========================================================= */

.payment-methods {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0,1fr));

  gap: 7px;

  margin-bottom: 15px;
}

.pay-btn {
  min-width: 0;
  height: 66px;

  padding: 7px 4px;

  border-radius: 14px;

  border:
    1px solid rgba(255,255,255,0.11);

  background:
    rgba(255,255,255,0.055);

  color:
    rgba(255,255,255,0.70);

  backdrop-filter:
    blur(20px)
    saturate(140%);

  -webkit-backdrop-filter:
    blur(20px)
    saturate(140%);

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  gap: 4px;

  font-size: 10px;
  font-weight: 750;

  cursor: pointer;

  transition: all .15s;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.10);
}

.pay-icon {
  width: 20px;
  height: 20px;
}

.pay-btn:hover {
  background:
    rgba(255,255,255,0.09);

  border-color:
    rgba(255,255,255,0.22);
}

.pay-btn.selected {
  background:
    rgba(255,255,255,0.16);

  border-color:
    rgba(255,255,255,0.36);

  color: #fff;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.28),
    0 7px 18px rgba(0,0,0,0.20);
}


/* =========================================================
   TOTAL
   ========================================================= */

.co-total {
  font-size: 34px;
  font-weight: 900;

  letter-spacing: -.04em;

  color: #fff;

  line-height: 1;

  margin:
    4px 0 16px;

  text-shadow:
    0 4px 18px rgba(0,0,0,0.35);
}


/* =========================================================
   EFECTIVO
   ========================================================= */

.cash-wrap {
  padding: 13px 16px 10px;
  margin-bottom: 12px;

  border-radius: 16px;

  background: rgba(255,255,255,0.035);
  border: 1px solid rgba(255,255,255,0.08);

  text-align: left;
}

.cash-label {
  margin-bottom: 2px;

  color: rgba(255,255,255,0.34);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: .12em;
  text-transform: uppercase;
}
.cash-field {
  width: 100%;
  height: 34px;

  padding: 0;

  border: none;
  border-radius: 0;

  background: transparent;

  color: #fff;

  font-family: inherit;
  font-size: 22px;
  font-weight: 850;

  letter-spacing: -.03em;

  text-align: center;

  outline: none;

  box-shadow: none;
}

.cash-field:focus {
  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;
}
.cash-feedback {
  margin-top: 7px;
  min-height: 20px;

  font-size: 13px;
  font-weight: 850;

  line-height: 1.2;
  text-align: center;

  letter-spacing: -.01em;

  transition:
    color .18s ease,
    background .18s ease,
    border-color .18s ease;
}
.cash-feedback.falta {
  color: #ff6868;
}

.cash-feedback.ok {
  color: #63e58c;
}
/* =========================================================
   MIXTO — COMPACTO
   ========================================================= */
.mixto-wrap {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  column-gap: 12px;
  row-gap: 4px;
  padding: 13px 16px 10px;
  margin-bottom: 12px;

  border-radius: 16px;

  background: rgba(255,255,255,0.035);
  border: 1px solid rgba(255,255,255,0.08);

  text-align: left;
}

.mixto-header {
  grid-column: 1 / -1;
  margin-bottom: 5px;

  color: rgba(255,255,255,0.34);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: .12em;
  text-transform: uppercase;
}

.mixto-row {
  display: flex;
  flex-direction: column;
  align-items: stretch;

  gap: 0;

  padding: 8px 2px 7px;

  margin: 0;

  border-bottom: none;
}

.mixto-row:last-of-type {
  border-bottom: none;
}

.mixto-lbl {
  width: auto;

  margin-bottom: 1px;

  color: rgba(255,255,255,0.38);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: .08em;
  text-transform: uppercase;
}

.mixto-field {
  width: 100%;
  height: 30px;

  padding: 0;

  border: none;
  border-radius: 0;

  background: transparent;

  color: #fff;

  font-family: inherit;
  font-size: 19px;
  font-weight: 800;

  letter-spacing: -.02em;

  text-align: center;

  outline: none;

  box-shadow: none;
}
.mixto-field:focus {
  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;
}

.mixto-status {
  grid-column: 1 / -1;
  margin-top: 9px;
  padding: 8px 10px;

  min-height: 24px;

  border-radius: 10px;

  font-size: 14px;
  font-weight: 850;

  line-height: 1.2;
  text-align: center;

  letter-spacing: -.01em;

  background: rgba(255,255,255,0.035);
  border: 1px solid rgba(255,255,255,0.06);
}

.mixto-status:empty {
  display: none;
}

.mixto-status.falta {
  color: #ff6868;

  background: rgba(255,80,80,0.065);
  border-color: rgba(255,100,100,0.13);
}

.mixto-status.ok {
  color: #63e58c;

  background: rgba(60,220,115,0.065);
  border-color: rgba(80,230,130,0.13);
}

/* =========================================================
   BOTONES ABAJO
   ========================================================= */

.co-btns {
  display:
    grid;

  grid-template-columns:
    .8fr 1.2fr;

  gap:
    8px;

  margin-top:
    3px;
}

.co-btn {
  min-width:
    0;

  height:
    44px;

  padding:
    0 12px;

  border-radius:
    13px;

  font-size:
    12px;

  font-weight:
    800;

  font-family:
    inherit;

  cursor:
    pointer;

  transition:
    all .15s;
}


/* CANCELAR */
.co-btn.cancel {
  background:
    rgba(255,255,255,0.045);

  border:
    1px solid rgba(255,255,255,0.10);

  color:
    rgba(255,255,255,0.55);

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);
}

.co-btn.cancel:hover {
  background:
    rgba(255,255,255,0.09);

  color: #fff;
}


/* CONFIRMAR — GLASS COMO LOGIN */
.co-btn.confirm {
  background:
    rgba(255,255,255,0.12);

  border:
    1px solid rgba(255,255,255,0.24);

  color: #fff;

  backdrop-filter:
    blur(24px)
    saturate(170%);

  -webkit-backdrop-filter:
    blur(24px)
    saturate(170%);

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.30),
    0 8px 22px rgba(0,0,0,0.26);
}

.co-btn.confirm:hover:not(:disabled) {
  background:
    rgba(255,255,255,0.19);

  border-color:
    rgba(255,255,255,0.38);

  transform:
    translateY(-1px);
}

.co-btn.confirm:disabled {
  opacity:
    .30;

  cursor:
    not-allowed;

  transform:
    none;

  box-shadow:
    none;
}


