#caja-modal.open { display:flex; }
.caja-panel {
  background: rgba(255,255,255,0.07);
  backdrop-filter: blur(48px) saturate(200%);
  -webkit-backdrop-filter: blur(48px) saturate(200%);
  border: 1.5px solid rgba(255,255,255,0.72);
  border-radius: 28px; padding: 36px 32px 30px;
  width: min(600px,94vw); color: #fff;
  box-shadow:
    0 2px 0 0 rgba(255,255,255,0.55) inset,
    0 -1px 0 0 rgba(255,255,255,0.18) inset,
    1px 0 0 0 rgba(255,255,255,0.22) inset,
    -1px 0 0 0 rgba(255,255,255,0.12) inset,
    0 40px 100px rgba(0,0,0,0.75),
    0 0 80px rgba(120,90,210,0.20);
}
.caja-step { display:none; flex-direction:column; gap:16px; }
.caja-step.active { display:flex; }
.caja-step-num {
  font-size:11px; font-weight:700; letter-spacing:.1em; text-transform:uppercase;
  color:var(--text-secondary); margin-bottom:2px;
}
.caja-title { font-size:22px; font-weight:900; letter-spacing:-.01em; }
.caja-sub { font-size:14px; color:var(--text-secondary); }
.caja-name-tag {
  background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.20);
  border-radius:12px; padding:12px 16px; font-size:15px; font-weight:700;
  color:var(--text-primary); text-align:center;
}
.caja-card-horiz {
  display:flex; align-items:center; gap:22px;
  background:rgba(14,10,30,0.88); border:1px solid rgba(255,255,255,0.38);
  border-radius:20px; padding:22px 26px;
}
.caja-abrir-square {
  width:86px; height:86px; border-radius:18px; border:1px solid rgba(255,255,255,0.22); flex-shrink:0;
  background:linear-gradient(145deg,rgba(255,255,255,0.16) 0%,rgba(255,255,255,0.06) 100%);
  color:#fff; font-size:13px; font-weight:800; cursor:pointer;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:5px;
  font-family:inherit; line-height:1.2;
  box-shadow:0 6px 22px rgba(0,0,0,0.45), inset 0 1.5px 0 rgba(255,255,255,0.28);
  transition:transform .12s, box-shadow .12s;
}
.caja-abrir-square:hover { transform:scale(1.05); background:linear-gradient(145deg,rgba(255,255,255,0.24) 0%,rgba(255,255,255,0.10) 100%); box-shadow:0 10px 32px rgba(0,0,0,0.55), inset 0 1.5px 0 rgba(255,255,255,0.35); }
.caja-card-right { flex:1; }
.caja-card-num {
  font-size:52px; font-weight:900; line-height:1; letter-spacing:-.02em;
  color:var(--text-primary);
}
.caja-card-cajera { font-size:15px; color:var(--text-secondary); margin-top:6px; font-weight:600; }
.caja-input-wrap { display:flex; flex-direction:column; gap:6px; }
.caja-input-label { font-size:11px; font-weight:700; color:var(--text-secondary); text-transform:uppercase; letter-spacing:.06em; }
.caja-input {
  width:100%; padding:22px 24px; border-radius:18px;
  border:2px solid rgba(255,255,255,0.70);
  background:linear-gradient(180deg,rgba(255,255,255,0.14) 0%,rgba(255,255,255,0.05) 100%);
  color:#fff; font-size:32px; font-weight:900; outline:none; text-align:center;
  font-family:inherit; transition:all .18s; box-sizing:border-box;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.18) inset,
    0 8px 28px rgba(0,0,0,0.40);
  letter-spacing:0.03em;
}
.caja-input:focus {
  border-color:rgba(255,255,255,0.90);
  background:linear-gradient(180deg,rgba(255,255,255,0.20) 0%,rgba(255,255,255,0.08) 100%);
  box-shadow:
    0 2px 0 rgba(255,255,255,0.25) inset,
    0 12px 36px rgba(0,0,0,0.50),
    0 0 0 3px rgba(255,255,255,0.18);
}
.caja-input.sm { font-size:22px; padding:16px 20px; }
.caja-cierre-row {
  display:grid; grid-template-columns:1fr 1fr; gap:10px;
}
.caja-result-grid {
  background:rgba(12,6,28,0.55); border:1px solid rgba(255,255,255,0.35);
  border-radius:14px; padding:14px 16px; display:flex; flex-direction:column; gap:8px;
}
.caja-result-row { display:flex; justify-content:space-between; align-items:center; font-size:13px; }
.caja-result-row .lbl { color:var(--text-secondary); font-weight:600; }
.caja-result-row .val { font-weight:800; }
.caja-result-row .val.ok    { color:#7dba82; }
.caja-result-row .val.falta { color:#ff6b6b; }
.caja-result-row .val.sobra { color:#f59e0b; }
.caja-result-total {
  border-top:1px solid rgba(255,255,255,0.35); padding-top:8px; margin-top:2px;
  font-size:15px; font-weight:900;
}
.caja-btn-primary {
  width:100%; padding:20px; border-radius:18px; border:none;
  background:linear-gradient(180deg,#ffffff 0%,#d8d8d8 55%,#c0c0c0 100%);
  color:#111; font-size:18px; font-weight:800; cursor:pointer;
  font-family:inherit; transition:all .18s; letter-spacing:0.02em;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.60) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 8px 28px rgba(0,0,0,0.45),
    0 3px 8px rgba(0,0,0,0.25);
}
.caja-btn-primary:hover {
  transform:translateY(-2px);
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.60) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 14px 36px rgba(0,0,0,0.52),
    0 4px 12px rgba(0,0,0,0.30);
}
.caja-btn-primary:active { transform:translateY(1px); }
.caja-btn-primary.green {
  background:linear-gradient(180deg,#6ee87a 0%,#3fcc50 55%,#28b03a 100%);
  color:#fff;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.55) inset,
    0 8px 28px rgba(50,180,70,0.45),
    0 3px 8px rgba(0,0,0,0.25);
}
.caja-btn-primary.red {
  background:linear-gradient(180deg,#f87171 0%,#dc2626 55%,#b91c1c 100%);
  color:#fff;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.40) inset,
    0 8px 28px rgba(200,40,40,0.45),
    0 3px 8px rgba(0,0,0,0.25);
}
.caja-btns { display:flex; gap:12px; }
.caja-btn-sec {
  flex:1; padding:16px; border-radius:16px;
  border:1.5px solid rgba(255,255,255,0.55);
  background:linear-gradient(180deg,rgba(255,255,255,0.18) 0%,rgba(255,255,255,0.08) 100%);
  color:rgba(255,255,255,0.85);
  font-size:15px; font-weight:700; cursor:pointer; font-family:inherit; transition:all .15s;
  box-shadow:
    0 1px 0 rgba(255,255,255,0.25) inset,
    0 4px 12px rgba(0,0,0,0.30);
}
.caja-btn-sec:hover {
  background:linear-gradient(180deg,rgba(255,255,255,0.25) 0%,rgba(255,255,255,0.12) 100%);
  color:#fff; transform:translateY(-1px);
}
.caja-estado-tag {
  display:inline-flex; align-items:center; gap:6px;
  font-size:12px; font-weight:700; padding:4px 12px; border-radius:8px;
}
.caja-estado-tag.abierta { background:rgba(100,155,105,0.14); color:#7dba82; border:1px solid rgba(165,80,50,0.42); }
.caja-estado-tag.cerrada { background:rgba(255,100,100,0.1); color:#ff6b6b; border:1px solid rgba(255,100,100,0.25); }

/* ========== MONITOR DE CAJAS ========== */
.caja-panel { overflow-y:auto; max-height:92dvh; }
.monitor-list-wrap { flex:1; overflow-y:auto; display:flex; flex-direction:column; gap:8px; max-height:300px; }
.monitor-card {
  background:rgba(14,10,30,0.88); border:1px solid rgba(255,255,255,0.35);
  border-radius:14px; padding:12px 14px;
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  flex-shrink:0;
}
.monitor-card-caja { font-size:15px; font-weight:800; color:var(--text-primary); }
.monitor-card-meta { font-size:12px; color:var(--text-secondary); margin-top:2px; }
.monitor-card-ap   { font-size:11px; color:var(--text-dim); margin-top:1px; }
.monitor-card-btn  {
  padding:8px 14px; border-radius:10px; border:none;
  background:linear-gradient(135deg,rgba(210,95,20,0.88),rgba(215,105,25,0.88));
  color:#fff; font-size:12px; font-weight:700; cursor:pointer; white-space:nowrap; font-family:inherit;
  transition:opacity .14s;
}
.monitor-card-btn:hover { opacity:.82; }
.monitor-card-badge {
  font-size:11px; font-weight:700; padding:4px 10px; border-radius:8px;
  background:rgba(100,155,105,0.14); color:#7dba82; border:1px solid rgba(165,80,50,0.42);
}
.monitor-open-btn {
  width:100%; padding:11px; border-radius:12px;
  border:1px solid rgba(230,115,30,0.42); background:rgba(80,55,155,0.14);
  color:var(--text-secondary); font-size:13px; font-weight:700;
  cursor:pointer; font-family:inherit; transition:all .14s; margin-top:4px;
}
.monitor-open-btn:hover { background:rgba(80,55,155,0.26); color:var(--text-primary); }

/* ========== CONFIRM TOAST ========== */
#confirm-toast {
  position:fixed; bottom:108px; left:50%; transform:translateX(-50%) translateY(20px);
  z-index:99999; pointer-events:none; opacity:0;
  transition:opacity .22s ease, transform .22s cubic-bezier(.34,1.4,.64,1);
  min-width:300px; max-width:90vw;
}
#confirm-toast.show {
  opacity:1; transform:translateX(-50%) translateY(0); pointer-events:all;
}
.ct-inner {
  background:linear-gradient(160deg,rgba(28,8,14,0.99),rgba(18,4,8,0.99));
  border:1px solid rgba(165,80,50,0.42); border-radius:22px;
  padding:20px 22px 16px;
  box-shadow:0 24px 72px rgba(0,0,0,0.85), 0 0 0 1px rgba(130,105,190,0.06),
    inset 0 1.5px 0 rgba(145,188,148,0.16);
  display:flex; flex-direction:column; gap:14px;
}
.ct-msg {
  font-size:15px; font-weight:700; color:var(--text-primary);
  text-align:center; line-height:1.4;
}
.ct-icon { font-size:24px; text-align:center; margin-bottom:-4px; }
.ct-btns { display:flex; gap:9px; }
.ct-btn {
  flex:1; padding:12px 10px; border-radius:13px; border:none;
  font-size:14px; font-weight:700; cursor:pointer; font-family:inherit;
  transition:all .14s; letter-spacing:.01em;
}
.ct-btn.cancel {
  background:rgba(16,12,32,0.84); border:1.5px solid rgba(255,255,255,0.35);
  color:var(--text-secondary);
}
.ct-btn.cancel:hover { background:rgba(14,10,30,0.86); color:var(--text-primary); }
.ct-btn.danger {
  background:linear-gradient(135deg,rgba(220,60,60,.9),rgba(180,30,30,.9));
  color:#fff; box-shadow:0 4px 16px rgba(200,40,40,0.35);
}
.ct-btn.danger:hover { transform:translateY(-1px); box-shadow:0 8px 24px rgba(200,40,40,0.5); }
.ct-btn.warn {
  background:linear-gradient(135deg,rgba(240,140,30,.9),rgba(200,100,10,.9));
  color:#fff; box-shadow:0 4px 16px rgba(220,120,20,0.35);
}
.ct-btn.warn:hover { transform:translateY(-1px); box-shadow:0 8px 24px rgba(220,120,20,0.5); }

/* ========== ORDENES MODAL ========== */
#ordenes-modal {
  display:none; position:fixed; inset:0; z-index:9300;
  align-items:flex-start; justify-content:center;
  background:rgba(5,3,15,0.86); backdrop-filter:blur(16px);
  padding:24px 16px 24px; overflow-y:auto;
}
#ordenes-modal.open { display:flex; }
.ord-panel {
  background: rgba(255,255,255,0.07);
  backdrop-filter: blur(48px) saturate(200%);
  -webkit-backdrop-filter: blur(48px) saturate(200%);
  border: 1.5px solid rgba(255,255,255,0.72);
  border-radius: 28px; color: #fff;
  padding: 32px 28px 28px; width: min(820px,96vw);
  box-shadow:
    0 2px 0 0 rgba(255,255,255,0.55) inset,
    0 -1px 0 0 rgba(255,255,255,0.18) inset,
    1px 0 0 0 rgba(255,255,255,0.22) inset,
    -1px 0 0 0 rgba(255,255,255,0.12) inset,
    0 40px 120px rgba(0,0,0,0.78),
    0 0 80px rgba(120,90,210,0.18);
}
.ord-search-wrap {
  position:relative; flex:1; min-width:180px;
}
.ord-search-wrap svg {
  position:absolute; left:14px; top:50%; transform:translateY(-50%);
  opacity:.4; pointer-events:none;
}
.ord-search {
  width:100%; padding:12px 14px 12px 40px; border-radius:14px;
  border:1.5px solid rgba(255,255,255,0.35);
  background:rgba(16,12,32,0.84); color:var(--text-primary);
  font-size:14px; outline:none; font-family:inherit; transition:border-color .15s;
  box-sizing:border-box;
}
.ord-search:focus { border-color:rgba(230,115,30,0.60); background:rgba(14,10,30,0.88); }
.ord-search::placeholder { color:var(--text-dim); }

.ord-list {
  display:flex; flex-direction:column; gap:12px;
  max-height:62vh; overflow-y:auto; padding-right:4px;
  scrollbar-width:thin; scrollbar-color:rgba(230,115,30,0.36) transparent;
}
.ord-list::-webkit-scrollbar { width:4px; }
.ord-list::-webkit-scrollbar-thumb { background:rgba(230,115,30,0.36); border-radius:4px; }

.ord-card {
  background:rgba(4,35,24,0.6);
  border:1px solid rgba(255,255,255,0.35);
  border-radius:20px; padding:20px 22px;
  display:grid; grid-template-columns:1fr auto;
  gap:14px; align-items:start;
  box-shadow:0 4px 20px rgba(0,0,0,0.4),
    inset 0 1.5px 0 rgba(145,188,148,0.08);
  transition: border-color .15s;
}
.ord-card:hover { border-color:rgba(165,80,50,0.42); }
.ord-card.anulada {
  opacity:.5; border-color:rgba(255,100,100,0.2);
  background:rgba(255,80,80,0.04);
}
.ord-left { display:flex; flex-direction:column; gap:10px; }
.ord-top { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
.ord-num {
  font-size:22px; font-weight:900; letter-spacing:-.02em;
  background:linear-gradient(135deg,#8c2e20,#6e1e14,#7a2518);
  -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text;
}
.ord-estado-badge {
  display:inline-flex; align-items:center; gap:5px;
  font-size:11px; font-weight:700; padding:4px 11px; border-radius:8px;
}
.ord-estado-badge.ok    { background:rgba(100,155,105,0.14); color:#7dba82; border:1px solid rgba(165,80,50,0.42); }
.ord-estado-badge.fail  { background:rgba(255,100,100,0.12); color:#ff6b6b; border:1px solid rgba(255,100,100,0.25); }
.ord-hora-caja {
  font-size:12px; color:var(--text-secondary); font-weight:600;
  margin-left:auto;
}
.ord-meta { font-size:12px; color:var(--text-secondary); }
.ord-prods {
  font-size:14px; font-weight:600; color:rgba(238,225,210,0.90);
  line-height:1.5;
}
.ord-total-row {
  display:flex; align-items:center; gap:10px; margin-top:2px;
}
.ord-metodo {
  font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.06em;
  background:rgba(100,28,40,0.14); border:1px solid rgba(255,255,255,0.28);
  padding:3px 10px; border-radius:7px; color:rgba(230,220,210,0.95);
}
.ord-total {
  font-size:20px; font-weight:900; letter-spacing:-.02em;
  color:var(--accent-bright);
}
.ord-right {
  display:flex; flex-direction:column; gap:9px; flex-shrink:0; min-width:130px;
}
.ord-btn {
  width:100%; padding:13px 10px; border-radius:14px; border:none;
  font-size:13px; font-weight:700; cursor:pointer; font-family:inherit;
  transition:all .15s; display:flex; align-items:center; justify-content:center; gap:7px;
  letter-spacing:.01em;
}
.ord-btn.print {
  background:linear-gradient(180deg,#ffffff 0%,#e0e0e0 52%,#c8c8c8 100%);
  border:1px solid rgba(255,255,255,0.90);
  color:#111; font-weight:800;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.58) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 6px 20px rgba(0,0,0,0.45);
}
.ord-btn.print:hover { transform:translateY(-2px); box-shadow:0 2px 0 rgba(255,255,255,0.95) inset,-1px 0 0 rgba(255,255,255,0.58) inset,0 1px 3px rgba(0,0,0,0.18) inset,0 12px 28px rgba(0,0,0,0.52); }
.ord-btn.void {
  background:linear-gradient(180deg,rgba(255,255,255,0.14) 0%,rgba(255,255,255,0.06) 100%);
  border:1.5px solid rgba(255,100,100,0.55);
  color:rgba(255,150,150,1); font-weight:700;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.18), 0 3px 10px rgba(0,0,0,0.28);
}
.ord-btn.void:hover { background:rgba(255,80,80,0.22); border-color:rgba(255,100,100,0.85); color:#fff; }
.ord-btn:disabled { opacity:.3; cursor:not-allowed; transform:none !important; box-shadow:none !important; }


/* Product cards */
.prod-card {
  border: 1px solid rgba(255,255,255,0.15) !important;
  box-shadow: 0 4px 20px rgba(0,0,0,0.55) !important;
  background: #1a1a1a !important;
  aspect-ratio: 1 / 1 !important;
}
.prod-card:hover {
  border-color: rgba(255,255,255,0.32) !important;
  box-shadow: 0 10px 36px rgba(0,0,0,0.72) !important;
}
.prod-card::before { display: none !important; }
.prod-img { background-color: transparent !important; object-fit: cover !important; }

/* Order panel — glass transparente estilo dock */
#order-panel {
  background: rgba(255,255,255,0.035) !important;
  backdrop-filter: blur(60px) saturate(200%) !important;
  -webkit-backdrop-filter: blur(60px) saturate(200%) !important;
  border: 1px solid rgba(255,255,255,0.12) !important;
  border-radius: 28px !important;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.18) inset,
    0 -1px 0 rgba(255,255,255,0.05) inset,
    1px 0 0 rgba(255,255,255,0.08) inset,
    -1px 0 0 rgba(255,255,255,0.05) inset,
    0 24px 80px rgba(0,0,0,0.50) !important;
}
#order-panel::before { background: linear-gradient(90deg,transparent,rgba(255,255,255,0.14) 40%,rgba(255,255,255,0.22) 50%,rgba(255,255,255,0.14) 60%,transparent) !important; }
#order-panel::after  { background: linear-gradient(175deg,rgba(255,255,255,0.04) 0%,transparent 40%) !important; }

/* Search bar */
.glass#products-panel {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
}

/* Order items */
.order-item {
  background: rgba(255,255,255,0.07) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border: 1px solid rgba(255,255,255,0.12) !important;
  box-shadow: 0 4px 16px rgba(0,0,0,0.18), inset 0 1px 0 rgba(255,255,255,0.16) !important;
}
.order-item::before { background: linear-gradient(180deg,rgba(255,255,255,0.07) 0%,transparent 100%) !important; }

/* Qty buttons */
.qty-btn {
  background: rgba(255,255,255,0.08) !important;
  border: 1px solid rgba(255,255,255,0.16) !important;
  backdrop-filter: blur(12px) !important;
}
.qty-btn:hover { background: rgba(255,255,255,0.16) !important; border-color: rgba(255,255,255,0.30) !important; }

/* Pedido compacto para tablet: nombre, precio y controles siempre visibles */
.order-item {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  gap: 5px 9px;
  align-items: center;
  padding: 10px 11px;
}
.oi-em {
  grid-column: 1;
  grid-row: 1 / 4;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  font-size: 23px;
}
.oi-em img { border-radius: 10px; }
.oi-info {
  grid-column: 2;
  grid-row: 1;
  width: 100%;
}
.oi-name {
  font-size: 13px;
  line-height: 1.2;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
}
.oi-price-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 5px;
  min-width: 0;
}
.oi-unit {
  font-size: 10px;
  white-space: nowrap;
}
.oi-tot {
  min-width: 0;
  font-size: 13px;
  line-height: 1.1;
  white-space: nowrap;
  text-align: right;
}
.oi-ctrl {
  grid-column: 2;
  grid-row: 2 / 4;
  justify-content: flex-start;
  gap: 5px;
}
.qty-btn {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  font-size: 16px;
}
.oi-qty {
