/* brillo superior */
#reportes-modal .rep-panel::before {
  content: '';

  position: absolute;

  top: 0;
  left: 12%;
  right: 12%;

  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,255,255,0.30),
      rgba(255,255,255,0.80),
      rgba(255,255,255,0.30),
      transparent
