}


/* =========================================================
   HEADER
   ========================================================= */

.rep-main-head {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 26px;
}


.rep-main-title {
  font-size: 21px;
  font-weight: 900;

  letter-spacing: .08em;

  color: #fff;
}


.rep-main-close {
  width: 38px;
  height: 38px;

  border-radius: 12px;

  border: 1px solid rgba(255,255,255,0.10);

  background: rgba(255,255,255,0.045);

  color: rgba(255,255,255,0.55);

  font-family: inherit;
  font-size: 22px;
  font-weight: 500;

  line-height: 1;

  cursor: pointer;

  transition: all .15s;
}


.rep-main-close:hover {
  background: rgba(255,255,255,0.10);
  border-color: rgba(255,255,255,0.20);

  color: #fff;
}


/* =========================================================
   OPCIONES
   ========================================================= */

.rep-main-options {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 12px;
}


.rep-main-option {
  position: relative;

  min-width: 0;

  height: 108px;

  padding: 18px 14px;

  border-radius: 18px;

  border: 1px solid rgba(255,255,255,0.10);

  background: rgba(255,255,255,0.045);

  color: rgba(255,255,255,0.60);

  font-family: inherit;

  cursor: pointer;

  display: flex;
  align-items: center;
  justify-content: center;

  text-align: center;

  transition:
    transform .15s ease,
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    box-shadow .15s ease;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.07);
}


.rep-main-option:hover {
  transform: translateY(-2px);

  background: rgba(255,255,255,0.08);

  border-color: rgba(255,255,255,0.20);

  color: #fff;
}


.rep-main-option.active {
  background: rgba(255,255,255,0.14);

  border-color: rgba(255,255,255,0.34);

  color: #fff;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.26),
    0 10px 28px rgba(0,0,0,0.24);
}


.rep-main-option-title {
  font-size: 14px;
  font-weight: 850;

  letter-spacing: .05em;

  white-space: nowrap;
}


.rep-main-option-check {
  position: absolute;

  top: 10px;
  right: 10px;

  width: 22px;
  height: 22px;

  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  background: rgba(255,255,255,0.08);

  border: 1px solid rgba(255,255,255,0.10);

  color: transparent;

  font-size: 11px;
  font-weight: 900;

  transition: all .15s;
}


.rep-main-option.active .rep-main-option-check {
  background: #fff;

  border-color: #fff;

  color: #111;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 600px) {

  #reportes-modal {
    padding: 14px;
  }


  #reportes-modal .rep-panel {
