/* =========================================================
   REPORTES — MINI MODAL DE FECHA
   ========================================================= */

.rep-flow-modal {
  display: none;

  position: fixed;
  inset: 0;

  z-index: 9800;

  align-items: center;
  justify-content: center;

  padding: 18px;

  background: rgba(0,0,0,0.82);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.rep-flow-modal.open {
  display: flex;
}


/* Panel base de los mini modales */
