  position: absolute;

  top: 0;
  left: 14%;
  right: 14%;

  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,255,255,0.22),
      rgba(255,255,255,0.75),
      rgba(255,255,255,0.22),
      transparent
    );

  pointer-events: none;
}


/* =========================================================
   HEADER MINI MODAL
   ========================================================= */

.rep-flow-head {
  display: flex;

  align-items: flex-start;
  justify-content: space-between;

  gap: 14px;

  margin-bottom: 18px;
}


.rep-flow-kicker {
  margin-bottom: 4px;

  color: rgba(255,255,255,0.36);

  font-size: 9px;
  font-weight: 850;

  letter-spacing: .13em;

