}


.rep-flow-title {
  color: #fff;

  font-size: 18px;
  font-weight: 900;

  letter-spacing: -.02em;
}


.rep-flow-close {
  width: 34px;
  height: 34px;

  flex-shrink: 0;

  border-radius: 11px;

  border: 1px solid rgba(255,255,255,0.10);

