/* ========== CONFIRM TOAST ========== */
#confirm-toast {
  position:fixed; bottom:108px; left:50%; transform:translateX(-50%) translateY(20px);
  z-index:99999; pointer-events:none; opacity:0;
  transition:opacity .22s ease, transform .22s cubic-bezier(.34,1.4,.64,1);
