/* ---- Reportes steps UI ---- */
.rep-step-label { font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.10em; color:var(--text-secondary); margin-bottom:12px; }
.rep-option-btn {
  display:flex; align-items:center; gap:14px;
  width:100%; padding:14px 16px; border-radius:16px; text-align:left;
  background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.12);
  color:#fff; cursor:pointer; font-family:inherit; transition:all .16s;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.09);
}
.rep-option-btn:hover { background:rgba(255,255,255,0.10); border-color:rgba(255,255,255,0.26); transform:translateY(-1px); }
.rep-option-btn.active { background:rgba(230,115,30,0.18); border-color:rgba(230,115,30,0.55); box-shadow:0 0 0 2px rgba(230,115,30,0.18), inset 0 1px 0 rgba(255,255,255,0.12); }
.rep-opt-icon { width:32px; height:32px; flex-shrink:0; display:flex; align-items:center; justify-content:center; }
.rep-opt-icon img { width:28px; height:28px; }
.rep-opt-info { flex:1; min-width:0; }
.rep-opt-title { font-size:15px; font-weight:800; color:#fff; }
.rep-opt-sub { font-size:12px; color:var(--text-secondary); margin-top:2px; line-height:1.3; }
.rep-opt-check {
  font-size:13px; font-weight:900; width:26px; height:26px; border-radius:50%;
  background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.14);
  display:flex; align-items:center; justify-content:center; flex-shrink:0;
  color:transparent; transition:all .15s;
}
.rep-option-btn.active .rep-opt-check { background:rgba(230,115,30,0.40); border-color:rgba(230,115,30,0.70); color:var(--accent-bright); }
.rep-date-trigger {
  display:flex; align-items:center; gap:12px; width:100%; padding:14px 16px;
  border:1px solid rgba(255,255,255,0.16); border-radius:16px;
  background:rgba(255,255,255,0.06); color:#fff; text-align:left;
  cursor:pointer; font-family:inherit; transition:background .15s, border-color .15s, transform .15s;
}
.rep-date-trigger:hover {
  background:rgba(230,115,30,0.14); border-color:rgba(230,115,30,0.52);
  transform:translateY(-1px);
}
.rep-date-trigger-icon {
  display:flex; align-items:center; justify-content:center; width:38px; height:38px;
  border-radius:12px; background:linear-gradient(145deg,rgba(230,115,30,.88),rgba(178,63,18,.88));
  color:#fff; font-size:10px; font-weight:900; letter-spacing:.06em; flex-shrink:0;
}
.rep-date-trigger-copy { display:flex; flex-direction:column; gap:3px; min-width:0; flex:1; }
.rep-date-trigger-copy strong { font-size:14px; font-weight:800; }
.rep-date-trigger-copy span { color:var(--text-secondary); font-size:12px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.rep-date-trigger-arrow { color:var(--accent-bright); font-size:26px; line-height:1; }
.rep-calendar-popover {
  display:none; position:fixed; inset:0; z-index:9800; align-items:center; justify-content:center;
  padding:18px; background:rgba(4,3,14,0.60); backdrop-filter:blur(10px);
}
.rep-calendar-popover.open { display:flex; }
.rep-date-dialog {
  width:min(390px,100%); padding:20px; border-radius:24px;
  background:linear-gradient(160deg,rgba(32,20,48,.98),rgba(15,10,30,.98));
  border:1px solid rgba(255,255,255,.22);
  box-shadow:0 28px 90px rgba(0,0,0,.78), inset 0 1px 0 rgba(255,255,255,.12);
}
.rep-date-dialog-head {
  display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:14px;
}
.rep-date-dialog-head > div { display:flex; flex-direction:column; gap:4px; }
.rep-date-dialog-kicker {
  color:var(--accent-bright); font-size:10px; font-weight:900; letter-spacing:.12em;
}
.rep-date-dialog-head strong { color:#fff; font-size:18px; }
.rep-date-dialog-close { width:34px; height:34px; font-size:14px; }
.rep-calendar {
  width:100%; padding:14px; box-sizing:border-box;
  border:1px solid rgba(255,255,255,0.14); border-radius:18px;
  background:rgba(10,8,28,0.62); box-shadow:inset 0 1px 0 rgba(255,255,255,0.08);
}
.rep-calendar-head {
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  color:#fff; font-size:15px; margin-bottom:12px;
}
.rep-cal-nav {
  width:32px; height:32px; border-radius:10px; border:1px solid rgba(255,255,255,0.16);
  background:rgba(255,255,255,0.08); color:#fff; font-size:22px; line-height:1;
  cursor:pointer; font-family:inherit; transition:background .15s, transform .15s;
}
.rep-cal-nav:hover { background:rgba(230,115,30,0.30); transform:translateY(-1px); }
.rep-cal-weekdays, .rep-calendar-grid {
  display:grid; grid-template-columns:repeat(7,1fr); gap:5px;
}
.rep-cal-weekdays {
  margin-bottom:6px; color:rgba(255,255,255,0.42); font-size:10px;
  font-weight:800; text-align:center; text-transform:uppercase;
}
.rep-calendar-grid button {
  min-height:34px; padding:0; border-radius:9px; border:1px solid transparent;
  background:transparent; color:rgba(255,255,255,0.82); font:700 12px inherit;
  cursor:pointer; transition:background .14s, color .14s, border-color .14s;
}
.rep-calendar-grid button:hover { background:rgba(230,115,30,0.22); color:#fff; }
.rep-calendar-grid button.other-month { color:rgba(255,255,255,0.24); }
.rep-calendar-grid button.today { border-color:rgba(230,115,30,0.62); }
.rep-calendar-grid button.selected,
.rep-calendar-grid button.in-range { background:rgba(230,115,30,0.34); color:#fff; }
.rep-calendar-grid button.selected { border-color:rgba(255,190,120,0.78); font-weight:900; }
.rep-date-footer {
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  width:min(100%, 360px); margin-top:10px; color:var(--text-secondary);
  font-size:12px; line-height:1.35;
}
.rep-date-clear {
  flex-shrink:0; border:0; background:transparent; color:var(--accent-bright);
  font:700 12px inherit; cursor:pointer; padding:4px 0;
}
.rep-date-clear:hover { color:#fff; }
.rep-date-apply {
  width:100%; margin-top:14px; padding:12px 16px; border:0; border-radius:13px;
  background:linear-gradient(135deg,rgba(230,115,30,.95),rgba(186,69,20,.95));
  color:#fff; font:800 14px inherit; cursor:pointer; box-shadow:0 8px 22px rgba(210,90,20,.28);
  transition:transform .15s, filter .15s;
}
.rep-date-apply:hover { transform:translateY(-1px); filter:brightness(1.08); }
@media (max-width:520px) {
  .rep-date-dialog { padding:16px; }
  .rep-calendar, .rep-date-footer { width:100%; }
  .rep-calendar-grid button { min-height:38px; }
}
