/* =========================================================
   ORDENES — REDISEÑO PROFESIONAL
   ========================================================= */

#ordenes-modal {
  background: rgba(0, 0, 0, 0.72) !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
  padding: 24px 16px !important;
}

.ord-panel {
  width: min(980px, 96vw) !important;
  max-height: 92vh !important;
  overflow: hidden !important;

  background:
    linear-gradient(
      180deg,
      rgba(24, 24, 24, 0.98) 0%,
      rgba(12, 12, 12, 0.99) 100%
    ) !important;

  border: 1px solid rgba(255,255,255,0.12) !important;
  border-radius: 24px !important;

  box-shadow:
    0 30px 80px rgba(0,0,0,0.72),
    inset 0 1px 0 rgba(255,255,255,0.06) !important;

  padding: 26px !important;
  color: #fff !important;
}

/* ---------- Encabezado ---------- */

.ord-header-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.ord-header-eyebrow {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .16em;
  color: rgba(255,255,255,0.42);
}

.ord-header-title {
  font-size: 28px !important;
  font-weight: 900 !important;
  letter-spacing: -0.03em !important;
  color: #fff !important;
  line-height: 1.05 !important;
}

.ord-header-subtitle {
  font-size: 12px;
  font-weight: 500;
  color: rgba(255,255,255,0.48);
  margin-top: 3px;
}

/* ---------- Cerrar ---------- */

#ordenes-modal .modal-close {
  width: 38px !important;
  height: 38px !important;
  border-radius: 12px !important;

  background: rgba(255,255,255,0.06) !important;
  border: 1px solid rgba(255,255,255,0.10) !important;
  color: rgba(255,255,255,0.72) !important;

  box-shadow: none !important;
  transition: all .15s ease !important;
}

#ordenes-modal .modal-close:hover {
  background: rgba(255,255,255,0.12) !important;
  color: #fff !important;
  border-color: rgba(255,255,255,0.18) !important;
}

/* ---------- Filtros ---------- */

#ordenes-modal .filter-btn {
  min-height: 42px;
  padding: 0 18px !important;

  border-radius: 12px !important;
  border: 1px solid rgba(255,255,255,0.10) !important;

  background: rgba(255,255,255,0.04) !important;
  color: rgba(255,255,255,0.62) !important;

  font-size: 12px !important;
  font-weight: 700 !important;
  letter-spacing: .01em !important;

  box-shadow: none !important;
}

#ordenes-modal .filter-btn:hover {
  background: rgba(255,255,255,0.08) !important;
  color: #fff !important;
}

#ordenes-modal .filter-btn.active {
  background: #ffffff !important;
  color: #111111 !important;
  border-color: #ffffff !important;
  box-shadow:
    0 5px 18px rgba(0,0,0,0.28) !important;
}

/* ---------- Buscador ---------- */

.ord-search-wrap {
  min-width: 280px !important;
}

.ord-search {
  height: 42px !important;
  padding: 0 16px 0 42px !important;

  border-radius: 12px !important;
  border: 1px solid rgba(255,255,255,0.10) !important;

  background: rgba(255,255,255,0.045) !important;
  color: #fff !important;

  font-size: 13px !important;
  font-weight: 600 !important;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.03) !important;
}

.ord-search::placeholder {
  color: rgba(255,255,255,0.30) !important;
}

.ord-search:focus {
  background: rgba(255,255,255,0.07) !important;
  border-color: rgba(255,255,255,0.28) !important;
  outline: none !important;
}

.ord-search-wrap svg {
  color: rgba(255,255,255,0.45) !important;
  opacity: 1 !important;
}

/* ---------- Contador ---------- */

#ord-count-label {
  color: rgba(255,255,255,0.38) !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  letter-spacing: .08em !important;
  text-transform: uppercase;
}

/* ---------- Lista ---------- */

.ord-list {
  max-height: 64vh !important;
  gap: 10px !important;
  padding-right: 6px !important;

  scrollbar-width: thin !important;
  scrollbar-color:
    rgba(255,255,255,0.16)
    transparent !important;
}

.ord-list::-webkit-scrollbar {
  width: 4px !important;
}

.ord-list::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.16) !important;
  border-radius: 10px !important;
}

/* ---------- Tarjeta de orden ---------- */

.ord-card {
  background: rgba(255,255,255,0.035) !important;

