    height:
      42px;

    margin-bottom:
      7px;
  }

  .co-title {
    font-size:
      18px;
  }

  .co-sub {
    font-size:
      10px;

    margin-bottom:
      12px;
  }

  .payment-methods {
    grid-template-columns:
      repeat(2, minmax(0,1fr));

    gap:
      6px;

    margin-bottom:
      11px;
  }

  .pay-btn {
    height:
      48px;

    flex-direction:
      row;

    gap:
      6px;
  }

  .pay-icon {
    width:
      18px;

    height:
      18px;
  }

  .co-total {
    font-size:
      29px;

    margin-bottom:
      11px;
  }

  .mixto-wrap,
  .cash-wrap {
    padding:
      9px 10px;

    margin-bottom:
      9px;
  }

  .mixto-row {
    grid-template-columns:
      58px 1fr;

    gap:
      6px;

    margin-bottom:
      5px;
  }

  .mixto-field {
    height:
