    0 -1px 0 rgba(255,255,255,0.05) inset,
    1px 0 0 rgba(255,255,255,0.08) inset,
    -1px 0 0 rgba(255,255,255,0.05) inset,
    0 24px 80px rgba(0,0,0,0.50) !important;
