/* =========================================================
   DESCUENTO DEL PEDIDO
   ========================================================= */

.order-discount-wrap {
  width: 88%;
  margin: 8px auto 10px;

  padding: 9px 11px;

  border-radius: 13px;

  background: rgba(255,255,255,0.028);
  border: 1px solid rgba(255,255,255,0.065);
}
.order-discount-top {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 2px;
}

.order-discount-label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
  text-align: center;
  color: rgba(255,255,255,0.55);
}

.order-discount-types {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 5px;

  margin-top: 2px;
}
.discount-type {
  min-width: 30px;
  height: 22px;

  padding: 0 7px;

  border-radius: 8px;

  border: 1px solid rgba(255,255,255,0.08);

  background: rgba(255,255,255,0.035);
  color: rgba(255,255,255,0.42);

  font-family: inherit;

  font-size: 9px;
  font-weight: 800;

  cursor: pointer;

  transition: all .15s ease;
}
.discount-type.active {
  background: rgba(255,255,255,0.16);
  border-color: rgba(255,255,255,0.28);

  color: #fff;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.20);
}

.order-discount-entry {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
}
.order-discount-input {
  width: 100%;
  height: 30px;

  padding: 0;

  border: none;
  outline: none;

  background: transparent;
  color: #fff;

  font-family: inherit;
  font-size: 20px;
  font-weight: 900;

  text-align: center;

  box-sizing: border-box;
}

.order-discount-input::placeholder {
  color: rgba(255,255,255,0.20);
}

.order-discount-input:focus {
  border: none;
  outline: none;
  background: transparent;
  box-shadow: none;
}

.order-discount-result {
  display: none;
}
/* NOTA + DESCUENTO EN UNA SOLA FILA */
.order-tools-row {
  width: 92%;
  margin: 0 auto;

  display: grid;
  grid-template-columns: 0.78fr 1.22fr;

  gap: 8px;
  align-items: stretch;
}
.order-tools-row .order-note-wrap,
.order-tools-row .order-discount-wrap,
.order-tools-row .totals {
  width: 100%;
  margin: 0;

  box-sizing: border-box;
}
/* =========================================================
   MODAL NOTA DEL PEDIDO
   ========================================================= */

#order-note-modal {
  display: none;

  position: fixed;
  inset: 0;
  z-index: 9200;

  align-items: center;
  justify-content: center;

  padding: 16px;

  background: rgba(0,0,0,0.10);

  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

#order-note-modal.open {
  display: flex;
}

.order-note-modal-panel {
  width: min(360px, 92vw);

  padding: 18px;

  border-radius: 22px;

  background:
    linear-gradient(
      160deg,
      rgba(28,28,28,0.96) 0%,
      rgba(12,12,12,0.94) 55%,
      rgba(8,8,8,0.97) 100%
    );

  border: 1px solid rgba(255,255,255,0.14);

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.16),
    0 24px 70px rgba(0,0,0,0.65);

  color: #fff;
}

.order-note-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 12px;
}

.order-note-modal-title {
  font-size: 11px;
  font-weight: 900;

  letter-spacing: .10em;

  color: rgba(255,255,255,0.72);
}

.order-note-modal-close {
  width: 28px;
  height: 28px;

  border: none;
  border-radius: 9px;

  background: rgba(255,255,255,0.06);
  color: rgba(255,255,255,0.55);

  font-size: 18px;
  line-height: 1;

  cursor: pointer;
}

.order-note-modal-input {
  width: 100%;
  min-height: 90px;

  padding: 12px;

  border-radius: 13px;

  border: 1px solid rgba(255,255,255,0.09);
  outline: none;

  background: rgba(255,255,255,0.035);
  color: #fff;

  font-family: inherit;
  font-size: 13px;
  font-weight: 600;

  line-height: 1.35;

  resize: none;

  box-sizing: border-box;
}

.order-note-modal-input::placeholder {
  color: rgba(255,255,255,0.25);
}

.order-note-modal-input:focus {
  border-color: rgba(255,255,255,0.20);
}

.order-note-modal-save {
  width: 100%;
  height: 40px;

  margin-top: 10px;

  border: 1px solid rgba(255,255,255,0.20);
  border-radius: 12px;

  background: rgba(255,255,255,0.11);
  color: #fff;

  font-family: inherit;
  font-size: 11px;
  font-weight: 900;

  letter-spacing: .06em;

  cursor: pointer;

  transition: all .15s ease;
}

.order-note-modal-save:hover {
  background: rgba(255,255,255,0.17);
