  .rep-main-option-check::after {
    font-size: 25px;
  }

}*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --glass-border:  rgba(255,200,120,0.01);
  --glass-shine:   rgba(255,200,140,0.12);
  --text-primary:  rgba(238,234,252,0.96);
  --text-secondary:rgba(210,190,170,0.78);
  --text-dim:      rgba(180,160,135,0.50);
  --accent: #d4af37;
  --accent-bright: #f5d76e;
  --accent-glow:   rgba(230,130,40,0.38);
}

  html, body {
    height: 100%; overflow: hidden;
    -webkit-text-size-adjust: 100%;
    touch-action: manipulation;
    font-family: -apple-system,'SF Pro Display','Helvetica Neue',Arial,sans-serif;
    background:
      radial-gradient(ellipse 80% 60% at 15% 10%, rgba(255,255,255,0.07) 0%, transparent 60%),
      radial-gradient(ellipse 70% 50% at 85% 90%, rgba(255,255,255,0.05) 0%, transparent 55%),
      radial-gradient(ellipse 50% 40% at 50% 50%, rgba(60,60,60,0.18) 0%, transparent 70%),
      linear-gradient(160deg, #000000 0%, #111111 40%, #0a0a0a 70%, #000000 100%);
    color: var(--text-primary);
  }

  body::before { display: none; }
  body::after  { display: none; }

  /* Figuras geométricas del fondo */
  .bg-shape { position: fixed; pointer-events: none; z-index: 0; }

  /* ── Círculos — esquina superior izquierda ── */
  .bg-c1 {
    width: 560px; height: 560px;
    border: 10px solid rgba(255,255,255,0.10); border-radius: 50%;
    top: -180px; left: -180px;
  }
  .bg-c2 {
    width: 360px; height: 360px;
    border: 7px solid rgba(255,255,255,0.07); border-radius: 50%;
    top: -90px; left: -90px;
  }
  /* ── Esquina inferior derecha ── */
  .bg-c3 {
    width: 500px; height: 500px;
    border: 10px solid rgba(255,255,255,0.09); border-radius: 50%;
    bottom: -160px; right: -160px;
  }
  .bg-c4 {
    width: 300px; height: 300px;
    border: 7px solid rgba(255,255,255,0.06); border-radius: 50%;
    bottom: -70px; right: -70px;
  }
  /* ── Círculos concéntricos centrales ── */
  .bg-c5 {
    width: 620px; height: 620px;
    border: 1.5px solid rgba(255,255,255,0.06); border-radius: 50%;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
  }
  .bg-c6 {
    width: 420px; height: 420px;
    border: 1.5px solid rgba(255,255,255,0.04); border-radius: 50%;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
  }
  /* ── Círculo superior derecho ── */
  .bg-c7 {
    width: 220px; height: 220px;
    border: 6px solid rgba(255,255,255,0.08); border-radius: 50%;
    top: 8%; right: 8%;
  }
  .bg-c8 {
    width: 130px; height: 130px;
    border: 5px solid rgba(255,255,255,0.14); border-radius: 50%;
    top: 14%; right: 13%;
  }
  /* ── Círculo inferior izquierdo ── */
  .bg-c9 {
    width: 180px; height: 180px;
    border: 6px solid rgba(255,255,255,0.07); border-radius: 50%;
    bottom: 12%; left: 6%;
  }
  /* ── Círculo extra — lado derecho medio ── */
  .bg-c10 {
    width: 110px; height: 110px;
    border: 5px solid rgba(255,255,255,0.12); border-radius: 50%;
    top: 45%; right: 4%;
  }
  /* ── Cuadrado rotado — centro-izquierda ── */
  .bg-sq {
    width: 190px; height: 190px;
    border: 5px solid rgba(255,255,255,0.05);
    transform: rotate(45deg);
    top: 55%; left: 5%;
  }
  /* ── Triángulo — arriba centro ── */
  .bg-tri {
    width: 0; height: 0;
    border-left: 90px solid transparent;
    border-right: 90px solid transparent;
    border-bottom: 155px solid rgba(255,255,255,0.04);
    top: 6%; left: 42%;
  }

  /* Blobs ocultos */
  .blob, .blob4 { display: none; }
  .glass {
    background: rgba(255,255,255,0.05);

    backdrop-filter: blur(30px) saturate(180%);
    -webkit-backdrop-filter: blur(30px) saturate(180%);

    border: 1px solid rgba(255,255,255,0.18);

    box-shadow:
      0 8px 32px rgba(0,0,0,0.15),
      inset 0 1px 1px rgba(255,255,255,0.3);

    border-radius: 22px;
  }

#app {
  position: relative; z-index:1;
  display: grid;
  grid-template-rows: 74px 1fr;
  /* Productos reciben al menos 60% del ancho, panel de órdenes max 38% */
  /* Layout fijo para tablet: catálogo a la izquierda y pedido a la derecha */
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-areas:
    "topbar topbar"
    "products order";
  height: 100dvh;
  gap: 8px;
  padding: 10px;
}

/* ── TOP BAR: search icon + user badge ── */
#top-bar {
  grid-area: topbar;
  display: flex;
  align-items: center;
  gap: 24px;
}

/* ── Search bar: compact 3D square that expands on focus ── */
#search-bar {
  width: 56px; height: 56px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  border-radius: 18px;
  overflow: hidden;
  transition: width 0.30s cubic-bezier(.4,0,.2,1);
  background: linear-gradient(180deg,#ffffff 0%,#d0d0d0 55%,#b8b8b8 100%);
  border: 1.5px solid rgba(255,255,255,0.92);
  box-shadow:
    0 2px 0 rgba(255,255,255,0.90) inset,
    -1px 0 0 rgba(255,255,255,0.50) inset,
    0 1px 3px rgba(0,0,0,0.20) inset,
    0 8px 24px rgba(0,0,0,0.50),
    0 3px 8px rgba(0,0,0,0.30);
  cursor: pointer;
}
#search-bar:focus-within {
  width: min(380px, 55vw);
}
#search-icon-btn {
  width: 56px; height: 56px; flex-shrink: 0;
  background: transparent; border: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  color: #1a1a1a; padding: 0;
}
#search-icon-btn svg { display: block; }
#search {
  flex: 1; width: 0; opacity: 0;
  background: transparent; border: none; outline: none;
  color: #111; font-size: 16px; font-family: inherit; font-weight: 600;
  padding: 0; min-width: 0;
  transition: opacity 0.22s;
}
#search-bar:focus-within #search {
  width: auto; opacity: 1; padding: 0 12px 0 0;
}
#search::placeholder { color: rgba(0,0,0,0.38); }
#search-clear {
  width: 24px; height: 24px; border-radius: 50%;
  background: rgba(0,0,0,0.12); border: none; color: #333;
  font-size: 11px; font-weight: 900; cursor: pointer; display: none;
  align-items: center; justify-content: center;
  flex-shrink: 0; margin-right: 10px;
}
#search-done {
  display: none;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-height: 32px;
  margin-right: 8px;
  padding: 0 12px;
  border: 1px solid rgba(0,0,0,0.18);
  border-radius: 10px;
  background: rgba(255,255,255,0.72);
  color: #222;
  font: 700 12px/1 inherit;
  cursor: pointer;
  touch-action: manipulation;
}
#search-bar:focus-within #search-done { display: flex; }
#search-done:active { transform: translateY(1px); }

/* ── Top user badge ── */
#top-user {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  border-radius: 16px;
  background: rgba(255,255,255,0.07);
  border: 1px solid rgba(255,255,255,0.14);
  box-shadow: 0 4px 16px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.15);
  backdrop-filter: blur(20px);
  margin-left: auto;
}
#top-user .user-badge-name { font-weight:800; font-size:13px; color:var(--text-primary); }
#top-user .user-badge-caja { color:var(--text-secondary); font-size:11px; margin-top:1px; }

#products-panel {
  grid-area: products;
  /* El panel hace el scroll, no el grid interno */
  overflow-y: auto;
  overflow-x: hidden;
  display: block;
  padding: 4px 4px 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.18) transparent;
}
#products-panel::-webkit-scrollbar { width: 4px; }
#products-panel::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.18); border-radius: 4px; }
#products-panel::before { display: none; }

#product-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  /* Sin height constraint: las filas crecen libremente según aspect-ratio */
  gap: 16px;
  padding: 0 0 96px;
}
#product-grid::-webkit-scrollbar { width: 4px; }
#product-grid::-webkit-scrollbar-thumb { background:rgba(230,115,30,0.36); border-radius:4px; }

.prod-card {
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 18px; cursor: pointer;
  transition: transform .2s cubic-bezier(.34,1.5,.64,1), box-shadow .2s ease, border-color .15s;
  box-shadow: 0 4px 20px rgba(0,0,0,0.55);
  position: relative; overflow: hidden;
  display: block;
  background: #1a1a1a;
  /* cuadrado perfecto que se adapta al ancho de la columna */
  aspect-ratio: 1 / 1;
}
.prod-card::before { display: none; }
.prod-card:hover { transform: scale(1.025); border-color: rgba(255,255,255,0.38); box-shadow: 0 8px 32px rgba(0,0,0,0.70); }
.prod-card:active { transform: scale(0.97); }

/* Imagen llena todo el cuadrado */
.prod-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 18px;
  display: block;
}
/* Fallback emoji — también llena el cuadrado */
.prod-emoji {
  position: absolute;
  inset: 0;
  font-size: 72px; line-height: 1;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255,255,255,0.04);
  border-radius: 18px;
}
/* Nombre superpuesto — franja inferior con degradado */
.prod-name {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 36px 12px 12px;
  background: linear-gradient(transparent, rgba(0,0,0,0.80));
  border-radius: 0 0 18px 18px;
  font-size: 14px; font-weight: 800; line-height: 1.25;
  color: #fff; letter-spacing: -.01em;
  z-index: 2;
}
/* Precio — badge esquina superior izquierda */
.prod-price {
  position: absolute;
  top: 10px; left: 10px;
  background: rgba(0,0,0,0.65);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,0.22);
  border-radius: 10px;
  padding: 4px 10px;
  font-size: 14px; font-weight: 800;
  color: #fff; letter-spacing: -.01em;
  line-height: 1.4;
  z-index: 2;
}
.prod-price span { display: none; }
/* Ocultar info-panel y botón + */
.prod-info { display: none; }
.prod-add  { display: none; }

#order-panel {
  grid-area: order;

  display: flex;
  flex-direction: column;

  padding: 18px 16px 96px;
  gap: 12px;

  overflow: hidden;

  position: relative;
}
#order-panel::before {
  content:''; position:absolute; top:0; left:6%; right:6%; height:1px;
  background: linear-gradient(90deg, transparent, rgba(235,150,65,0.45) 25%,
    rgba(255,185,90,0.70) 50%, rgba(235,150,65,0.45) 75%, transparent);
  border-radius:50%; pointer-events:none;
}
#order-panel::after {
  content:''; position:absolute; inset:1px; border-radius:25px;
  background: linear-gradient(175deg,rgba(255,255,255,0.04) 0%,transparent 40%,rgba(0,0,0,0.12) 100%);
  pointer-events:none;
}

.order-hd { display: flex; align-items: center; justify-content: space-between; position:relative; z-index:1; }
.order-title { font-size:15px; font-weight:700; letter-spacing:-.01em; }
.order-badge {
  background:rgba(80,55,155,0.22); border:1px solid rgba(255,200,120,0.5);
  color:rgba(145,190,148,0.95); font-size:11px; font-weight:700;
  padding:3px 9px; border-radius:10px; box-shadow: 0 0 10px rgba(230,115,30,0.36);
}
.order-clear {
  font-size:11px; font-weight:600; cursor:pointer; letter-spacing:.04em;
  color:rgba(185,65,55,0.70); padding:4px 10px; border-radius:9px;
  border:1px solid rgba(185,65,55,0.22); background:rgba(185,65,55,0.08); transition: all .14s;
}
.order-clear:hover { color:rgba(185,65,55,0.95); background:rgba(185,65,55,0.18); }

#order-list {
  flex:1; overflow-y:auto; display:flex; flex-direction:column; gap:8px;
  padding-right:2px; scrollbar-width:thin; scrollbar-color:rgba(230,115,30,0.36) transparent;
  position:relative; z-index:1;
}
#order-list::-webkit-scrollbar { width:3px; }
#order-list::-webkit-scrollbar-thumb { background:rgba(230,115,30,0.36); border-radius:3px; }

.order-empty {
  flex:1; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:10px;
  color:var(--text-dim); font-size:13px; text-align:center; padding:16px;
}
.order-empty-icon { font-size:42px; opacity:.3; }

.order-item {
  background: rgba(14,10,30,0.88);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255,255,255,0.35);
  border-radius: 18px; padding: 14px 16px;
  display: flex; align-items: center; gap: 12px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.4),
    inset 0 1.5px 0 rgba(255,200,120,0.20),
    inset 0 -1px 0 rgba(0,0,0,0.2);
  animation: slideIn .2s cubic-bezier(.34,1.4,.64,1);
  position: relative; overflow: hidden;
}
.order-item::before {
  content:''; position:absolute; top:0; left:0; right:0; height:40%;
  background: linear-gradient(180deg,rgba(255,255,255,0.03) 0%,transparent 100%);
  border-radius: 18px 18px 0 0; pointer-events:none;
}
@keyframes slideIn {
  from { opacity:0; transform:translateX(14px) scale(0.96); }
  to   { opacity:1; transform:translateX(0) scale(1); }
}
.oi-em {
  font-size:28px; flex-shrink:0;
  width:52px; height:52px; border-radius:12px;
  overflow:hidden; display:flex; align-items:center; justify-content:center;
  background: rgba(255,255,255,0.06);
}
.oi-em img {
  width:100%; height:100%; object-fit:cover; display:block; border-radius:12px;
}
.oi-info { flex:1; min-width:0; }
.oi-name { font-size:15px; font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.oi-unit { font-size:12px; color:var(--text-secondary); margin-top:2px; }
.oi-ctrl { display:flex; align-items:center; gap:7px; flex-shrink:0; }
.qty-btn {
  width:30px; height:30px; border-radius:10px;
  border:1px solid rgba(155,70,45,0.50); background:rgba(18,5,10,0.80);
  color:#ffffff; font-size:17px;
  display:flex; align-items:center; justify-content:center;
  cursor:pointer; transition:all .12s; flex-shrink:0; line-height:1;
  box-shadow: inset 0 1px 0 rgba(255,200,120,0.18);
}
.qty-btn:hover { background:rgba(190,140,75,0.25); border-color:rgba(190,140,75,0.55); }
.qty-btn.rm { color:rgba(255,85,100,0.8); border-color:rgba(255,85,100,0.22); }
.qty-btn.rm:hover { background:rgba(255,85,100,0.18); }
.oi-qty { font-size:17px; font-weight:700; min-width:22px; text-align:center; }
.oi-tot { font-size:16px; font-weight:700; color:var(--accent-bright); min-width:64px; text-align:right; }

.hr {
  height:1px; flex-shrink:0;
  background:linear-gradient(90deg,transparent,rgba(135,110,195,0.18) 30%,rgba(185,130,78,0.35) 50%,rgba(135,110,195,0.18) 70%,transparent);
  position:relative; z-index:1;
}
.totals {
  width: 100%;
  margin: 0;

  display: flex;
  flex-direction: column;
  justify-content: center;

  gap: 4px;

  flex-shrink: 0;

  position: relative;
  z-index: 1;

  padding: 9px 10px;

  border-radius: 13px;

  background: rgba(255,255,255,0.028);
  border: 1px solid rgba(255,255,255,0.065);

  box-sizing: border-box;
}
.tot-row { display:flex; justify-content:space-between; align-items:center; }
.tot-lbl {
  font-size: 8px;font-weight:800; letter-spacing:.10em; color:var(--text-secondary); text-transform:uppercase; }
.tot-val {
  font-size: 11px;font-weight:700; color:var(--text-primary); }
.tot-divider {
  height:1px; margin: 3px 0;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,0.25) 30%,rgba(255,255,255,0.40) 50%,rgba(255,255,255,0.25) 70%,transparent);
}
.tot-main {
  display: flex;
  justify-content: space-between;
  align-items: baseline;

  padding: 2px 0 0;
}
.tot-main-lbl {
  font-size:10px;font-weight:900; letter-spacing:.14em; color:rgba(255,255,255,0.55); text-transform:uppercase;
}
.tot-main-val {
  font-size: 17px;font-weight:900; letter-spacing:-.02em; line-height:1;
  color:#fff;
  white-space: nowrap;
  text-shadow: 0 2px 12px rgba(0,0,0,0.40);
}
.order-num-row {
  font-size:10px; font-weight:800; letter-spacing:.12em;
  color:rgba(255,255,255,0.35); margin-top:-4px; position:relative; z-index:1;
}
.order-num-val {
  color:var(--accent); font-size:12px; font-weight:900;
}

.btn-checkout {
  width:88%;
  margin-left:auto;
  margin-right:auto;
  padding:13px 16px;
  border-radius:16px;
  border:none;
  background:linear-gradient(180deg,#ffffff 0%,#d8d8d8 52%,#bdbdbd 100%);
  color:#111; font-size:14px; font-weight:900; letter-spacing:.06em; cursor:pointer;
  transition:all .18s; font-family:inherit; flex-shrink:0;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.58) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 8px 28px rgba(0,0,0,0.50),
    0 3px 8px rgba(0,0,0,0.28);
  position:relative; overflow:hidden; z-index:1;
}
.btn-checkout::before {
  content:''; position:absolute; top:0; left:0; right:0; height:48%;
  background:linear-gradient(180deg,rgba(255,255,255,0.40) 0%,transparent 100%);
  border-radius:18px 18px 0 0; pointer-events:none;
}
.btn-checkout:hover {
  transform:translateY(-2px);
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.58) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 14px 36px rgba(0,0,0,0.55),
    0 4px 12px rgba(0,0,0,0.32);
}
.btn-checkout:active { transform:scale(0.98); }
.btn-checkout:disabled { opacity:.3; cursor:not-allowed; transform:none; box-shadow:none; }
.post-sale-print {
  display:none;
   margin-top:12px;
   padding:12px;
  border:1px solid rgba(74,222,128,0.28);
  border-radius:14px;
  background:rgba(74,222,128,0.08);
}
.post-sale-print.show { display:block; }
.co-panel > .post-sale-print {
   width:100%;
   box-sizing:border-box;
   margin-top:16px;
}
.post-sale-print-msg {
  color:rgba(220,255,230,.84);
   font-size:12px;
  font-weight:700;
  text-align:center;
   margin-bottom:10px;
}
.post-sale-print-btn {
  width:100%;
  border:1px solid rgba(255,255,255,.76);
  border-radius:11px;
   padding:12px 12px;
  background:linear-gradient(180deg,#fff 0%,#dedede 55%,#c4c4c4 100%);
  color:#111;
   font:900 13px/1.1 inherit;
   letter-spacing:.02em;
  cursor:pointer;
  box-shadow:0 2px 0 rgba(255,255,255,.9) inset,0 5px 14px rgba(0,0,0,.25);
}
.post-sale-print-btn:disabled { opacity:.55; cursor:wait; }

#dock-wrap {
  position: fixed; bottom:22px; left:50%; transform:translateX(-50%);
  z-index: 1000; user-select:none; -webkit-user-select:none;
}
.dock {
  display:flex; align-items:center; gap:18px;
  padding:14px 22px; border-radius:38px; position:relative;
  background: rgba(255,255,255,.06);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border:1px solid rgba(255,255,255,0.28);
  box-shadow:0 6px 32px rgba(0,0,0,0.22), 0 2px 6px rgba(0,0,0,0.12),
    inset 0 1.5px 0 rgba(255,255,255,0.40), inset 0 -1px 0 rgba(0,0,0,0.08);
}
.dock::before {
  content:''; position:absolute; top:0; left:10%; right:10%; height:1px;
  background:linear-gradient(90deg, transparent, rgba(255,200,120,0.5) 25%,
    rgba(145,188,148,0.7) 50%, rgba(255,200,120,0.5) 75%, transparent);
  border-radius:50%; pointer-events:none;
}
.dock::after {
  content:''; position:absolute; inset:1px; border-radius:37px;
  background:linear-gradient(175deg,rgba(255,255,255,0.04) 0%,transparent 45%,rgba(0,0,0,0.1) 100%);
  pointer-events:none;
}
.dock-slot {
  position:relative; display:flex; flex-direction:column;
  align-items:center; gap:5px; cursor:pointer;
}
.dock-icon {
  width:62px; height:62px; border-radius:16px;
  display:flex; align-items:center; justify-content:center;
  transition:transform .22s cubic-bezier(.34,1.6,.64,1), box-shadow .22s ease, background .22s ease;
  background: rgba(4,2,14,0.92);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border: 1px solid rgba(255,255,255,0.38);
  border-bottom-color: rgba(255,255,255,0.14);
  box-shadow:
    0 6px 22px rgba(0,0,0,0.65),
    inset 0 1.5px 0 rgba(255,255,255,0.38),
    inset 0 -1px 0 rgba(0,0,0,0.35);
  position:relative; overflow:hidden;
}
.dock-icon::before {
  content:''; position:absolute; inset:0; border-radius:15px;
  background: linear-gradient(160deg,rgba(255,255,255,0.30) 0%,rgba(255,255,255,0.05) 45%, transparent 100%);
  pointer-events:none;
}
.dock-icon img {
  width:34px; height:34px; object-fit:contain;
  filter:invert(1) brightness(0.95);
  pointer-events:none; position:relative; z-index:1;
}
.dock-label {
  position:absolute; bottom:-24px; left:50%; transform:translateX(-50%);
  font-size:10px; font-weight:600; color:var(--text-secondary);
  white-space:nowrap; letter-spacing:.02em; pointer-events:none;
  opacity:0; transition:opacity .18s ease;
}
.dock-slot:hover .dock-label { opacity:1; }
.dock-slot:hover .dock-icon {
  transform:scale(1.1) translateY(-5px);
  background: rgba(14,8,38,0.96);
  box-shadow:0 10px 32px rgba(0,0,0,0.75), 0 0 0 1px rgba(255,255,255,0.45),
    inset 0 1.5px 0 rgba(255,255,255,0.50);
}
.dock-slot.selected .dock-icon {
  transform:scale(1.2) translateY(-8px);
  background: rgba(255,255,255,0.18);
  border-color: rgba(255,255,255,0.60);
  box-shadow:0 8px 28px rgba(0,0,0,0.20), 0 0 0 2px rgba(200,180,255,0.65),
    0 0 20px rgba(180,150,255,0.25),
    inset 0 1.5px 0 rgba(255,255,255,0.65);
  animation:selPulse 2s ease-in-out infinite;
}
@keyframes selPulse {
  0%,100% { box-shadow:0 14px 42px rgba(0,0,0,.65),0 4px 16px rgba(0,0,0,.5),
    0 0 0 2px rgba(130,170,135,.9),0 0 28px rgba(130,170,135,.45),
    inset 0 1.5px 0 rgba(110,231,183,.28); }
  50% { box-shadow:0 14px 42px rgba(0,0,0,.65),0 4px 16px rgba(0,0,0,.5),
    0 0 0 2.5px rgba(255,200,120,1),0 0 44px rgba(130,170,135,.65),
    inset 0 1.5px 0 rgba(110,231,183,.28); }
}
.edit-btn {
  position:absolute; top:-7px; right:-7px; z-index:10;
  width:20px; height:20px; border-radius:50%;
  background:rgba(245,240,255,0.92); border:1px solid rgba(255,200,120,0.5);
  font-size:10px; display:none; align-items:center; justify-content:center;
  cursor:pointer; color:rgba(230,220,210,0.95); box-shadow:0 2px 8px rgba(0,0,0,0.5);
}
.dock-slot.selected .edit-btn { display:flex; }

#edit-modal {
  display:none; position:fixed; inset:0; z-index:9999;
  align-items:center; justify-content:center;
  background:rgba(16,12,32,0.84); backdrop-filter:blur(12px);
}
#edit-modal.open { display:flex; }
.edit-panel {
  background: rgba(255,255,255,0.07);
  backdrop-filter: blur(48px) saturate(200%);
  -webkit-backdrop-filter: blur(48px) saturate(200%);
  border: 1.5px solid rgba(255,255,255,0.72);
  border-radius: 22px; padding: 24px 22px; color: #fff;
  width: min(340px,90vw);
  box-shadow:
    0 2px 0 0 rgba(255,255,255,0.55) inset,
    0 -1px 0 0 rgba(255,255,255,0.18) inset,
    1px 0 0 0 rgba(255,255,255,0.22) inset,
    -1px 0 0 0 rgba(255,255,255,0.12) inset,
    0 32px 80px rgba(0,0,0,0.72),
    0 0 60px rgba(120,90,210,0.18);
}
.ep-title { font-size:17px; font-weight:800; margin-bottom:16px; color:#fff; letter-spacing:-.01em; }
.ep-field { margin-bottom:12px; }
.ep-label { font-size:12px; font-weight:700; color:rgba(255,255,255,0.75); letter-spacing:.06em; text-transform:uppercase; margin-bottom:5px; }
.ep-input {
  width:100%; padding:9px 12px; border-radius:11px;
  background:rgba(255,255,255,0.10); border:1.5px solid rgba(255,255,255,0.35);
  color:#fff; font-size:14px; font-weight:600; font-family:inherit; outline:none; transition:border-color .14s;
}
.ep-input::placeholder { color:rgba(255,255,255,0.40); }
.ep-input:focus { border-color:rgba(255,255,255,0.75); background:rgba(255,255,255,0.14); }
.ep-actions { display:flex; gap:9px; margin-top:16px; }
.ep-btn {
  flex:1; padding:11px; border-radius:12px; border:none;
  font-size:14px; font-weight:700; cursor:pointer; font-family:inherit; transition:all .14s;
}
.ep-btn.cancel { background:rgba(255,255,255,0.10); border:1.5px solid rgba(255,255,255,0.35); color:rgba(255,255,255,0.85); }
.ep-btn.cancel:hover { background:rgba(255,255,255,0.18); color:#fff; }
.ep-btn.save { background:linear-gradient(135deg,rgba(210,95,20,0.88),rgba(215,105,25,0.88)); backdrop-filter:blur(8px); border:1.5px solid rgba(255,255,255,0.45); color:#fff; font-weight:800; box-shadow:0 4px 18px rgba(200,85,15,0.50); }
.ep-btn.save:hover { transform:translateY(-1px); box-shadow:0 6px 24px rgba(200,85,15,0.65); }

/* =========================================================
   CHECKOUT — MISMO LENGUAJE VISUAL DEL LOGIN
   ========================================================= */

#checkout-modal {
  display: none;
  position: fixed;
  top: var(--checkout-viewport-top, 0px);
  right: 0;
  left: 0;
  height: var(--checkout-viewport-height, 100dvh);
  min-height: 0;
  bottom: auto;
  z-index: 9000;

  align-items: flex-start;
  justify-content: center;

  padding: max(8px, env(safe-area-inset-top, 0px)) 18px 12px;

  background: rgba(0,0,0,0.12);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

#checkout-modal.open {
  display: flex;
}


/* PANEL — MISMO ESTILO QUE LOGIN */
.co-panel {
  position: relative;
  z-index: 1;

  width: min(440px, 94vw);
  max-height: min(94dvh, calc(var(--checkout-viewport-height, 100dvh) - 36px));

  overflow-y: auto;
  overflow-x: hidden;

  padding: 28px 26px 24px;

  border-radius: 32px;

  background:
  linear-gradient(
    160deg,
    rgba(28,28,28,0.96) 0%,
    rgba(12,12,12,0.94) 55%,
    rgba(8,8,8,0.97) 100%
  );

  backdrop-filter:
    blur(80px)
    saturate(140%);

  -webkit-backdrop-filter:
    blur(80px)
    saturate(140%);

  border: 1px solid rgba(255,255,255,0.14);
  box-shadow:
  0 2px 0 rgba(255,255,255,0.18) inset,
  0 -1px 0 rgba(255,255,255,0.04) inset,
  0 28px 80px rgba(0,0,0,0.72);
  text-align: center;
  color: #fff;
  scroll-padding-block: 14px;
}

/*
 * En Android, el teclado puede reducir el visual viewport sin cambiar el
 * layout viewport. El modal usa esas variables para centrarse en el espacio
 * realmente visible y evitar que el botón de confirmación quede bajo el IME.
 */
#checkout-modal.keyboard-open {
  align-items: flex-start;
  padding-top: max(8px, calc(var(--checkout-viewport-top, 0px) + 8px));
  padding-bottom: 10px;
}

#checkout-modal.keyboard-open .co-panel {
  max-height: calc(var(--checkout-viewport-height, 100dvh) - 20px);
}
/* brillo superior igual al login */
.co-panel::before {
  content: '';

  position: absolute;

  top: 0;
  left: 12%;
  right: 12%;

  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,255,255,0.30),
      rgba(255,255,255,0.80),
      rgba(255,255,255,0.30),
      transparent
    );

  pointer-events: none;
}


/* ICONO */
.co-icon {
  width: 48px;
  height: 48px;

  margin: 0 auto 10px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 16px;

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,0.14),
      rgba(255,255,255,0.04)
    );

  border:
    1px solid rgba(255,255,255,0.15);

  color:
    rgba(255,255,255,0.80) !important;

  box-shadow:
    0 8px 26px rgba(0,0,0,0.40),
    inset 0 1px 0 rgba(255,255,255,0.25);
}

.co-icon svg {
  width: 24px !important;
  height: 24px !important;
}


/* TITULO */
.co-title {
  font-size: 21px;
  font-weight: 900;

  letter-spacing: -.025em;

  color: #fff;

  margin-bottom: 2px;
}

.co-sub {
  font-size: 12px;
  font-weight: 500;

  color:
    rgba(255,255,255,0.38);

  margin-bottom: 16px;
}


/* =========================================================
   METODOS
   ========================================================= */

.payment-methods {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0,1fr));

  gap: 7px;

  margin-bottom: 15px;
}

.pay-btn {
  min-width: 0;
  height: 66px;

  padding: 7px 4px;

  border-radius: 14px;

  border:
    1px solid rgba(255,255,255,0.11);

  background:
    rgba(255,255,255,0.055);

  color:
    rgba(255,255,255,0.70);

  backdrop-filter:
    blur(20px)
    saturate(140%);

  -webkit-backdrop-filter:
    blur(20px)
    saturate(140%);

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  gap: 4px;

  font-size: 10px;
  font-weight: 750;

  cursor: pointer;

  transition: all .15s;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.10);
}

.pay-icon {
  width: 20px;
  height: 20px;
}

.pay-btn:hover {
  background:
    rgba(255,255,255,0.09);

  border-color:
    rgba(255,255,255,0.22);
}

.pay-btn.selected {
  background:
    rgba(255,255,255,0.16);

  border-color:
    rgba(255,255,255,0.36);

  color: #fff;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.28),
    0 7px 18px rgba(0,0,0,0.20);
}


/* =========================================================
   TOTAL
   ========================================================= */

.co-total {
  font-size: 34px;
  font-weight: 900;

  letter-spacing: -.04em;

  color: #fff;

  line-height: 1;

  margin:
    4px 0 16px;

  text-shadow:
    0 4px 18px rgba(0,0,0,0.35);
}


/* =========================================================
   EFECTIVO
   ========================================================= */

.cash-wrap {
  padding: 13px 16px 10px;
  margin-bottom: 12px;

  border-radius: 16px;

  background: rgba(255,255,255,0.035);
  border: 1px solid rgba(255,255,255,0.08);

  text-align: left;
}

.cash-label {
  margin-bottom: 2px;

  color: rgba(255,255,255,0.34);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: .12em;
  text-transform: uppercase;
}
.cash-field {
  width: 100%;
  height: 34px;

  padding: 0;

  border: none;
  border-radius: 0;

  background: transparent;

  color: #fff;

  font-family: inherit;
  font-size: 22px;
  font-weight: 850;

  letter-spacing: -.03em;

  text-align: center;

  outline: none;

  box-shadow: none;
}

.cash-field:focus {
  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;
}
.cash-feedback {
  margin-top: 7px;
  min-height: 20px;

  font-size: 13px;
  font-weight: 850;

  line-height: 1.2;
  text-align: center;

  letter-spacing: -.01em;

  transition:
    color .18s ease,
    background .18s ease,
    border-color .18s ease;
}
.cash-feedback.falta {
  color: #ff6868;
}

.cash-feedback.ok {
  color: #63e58c;
}
/* =========================================================
   MIXTO — COMPACTO
   ========================================================= */
.mixto-wrap {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  column-gap: 12px;
  row-gap: 4px;
  padding: 13px 16px 10px;
  margin-bottom: 12px;

  border-radius: 16px;

  background: rgba(255,255,255,0.035);
  border: 1px solid rgba(255,255,255,0.08);

  text-align: left;
}

.mixto-header {
  grid-column: 1 / -1;
  margin-bottom: 5px;

  color: rgba(255,255,255,0.34);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: .12em;
  text-transform: uppercase;
}

.mixto-row {
  display: flex;
  flex-direction: column;
  align-items: stretch;

  gap: 0;

  padding: 8px 2px 7px;

  margin: 0;

  border-bottom: none;
}

.mixto-row:last-of-type {
  border-bottom: none;
}

.mixto-lbl {
  width: auto;

  margin-bottom: 1px;

  color: rgba(255,255,255,0.38);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: .08em;
  text-transform: uppercase;
}

.mixto-field {
  width: 100%;
  height: 30px;

  padding: 0;

  border: none;
  border-radius: 0;

  background: transparent;

  color: #fff;

  font-family: inherit;
  font-size: 19px;
  font-weight: 800;

  letter-spacing: -.02em;

  text-align: center;

  outline: none;

  box-shadow: none;
}
.mixto-field:focus {
  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;
}

.mixto-status {
  grid-column: 1 / -1;
  margin-top: 9px;
  padding: 8px 10px;

  min-height: 24px;

  border-radius: 10px;

  font-size: 14px;
  font-weight: 850;

  line-height: 1.2;
  text-align: center;

  letter-spacing: -.01em;

  background: rgba(255,255,255,0.035);
  border: 1px solid rgba(255,255,255,0.06);
}

.mixto-status:empty {
  display: none;
}

.mixto-status.falta {
  color: #ff6868;

  background: rgba(255,80,80,0.065);
  border-color: rgba(255,100,100,0.13);
}

.mixto-status.ok {
  color: #63e58c;

  background: rgba(60,220,115,0.065);
  border-color: rgba(80,230,130,0.13);
}

/* =========================================================
   BOTONES ABAJO
   ========================================================= */

.co-btns {
  display:
    grid;

  grid-template-columns:
    .8fr 1.2fr;

  gap:
    8px;

  margin-top:
    3px;
}

.co-btn {
  min-width:
    0;

  height:
    44px;

  padding:
    0 12px;

  border-radius:
    13px;

  font-size:
    12px;

  font-weight:
    800;

  font-family:
    inherit;

  cursor:
    pointer;

  transition:
    all .15s;
}


/* CANCELAR */
.co-btn.cancel {
  background:
    rgba(255,255,255,0.045);

  border:
    1px solid rgba(255,255,255,0.10);

  color:
    rgba(255,255,255,0.55);

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);
}

.co-btn.cancel:hover {
  background:
    rgba(255,255,255,0.09);

  color: #fff;
}


/* CONFIRMAR — GLASS COMO LOGIN */
.co-btn.confirm {
  background:
    rgba(255,255,255,0.12);

  border:
    1px solid rgba(255,255,255,0.24);

  color: #fff;

  backdrop-filter:
    blur(24px)
    saturate(170%);

  -webkit-backdrop-filter:
    blur(24px)
    saturate(170%);

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.30),
    0 8px 22px rgba(0,0,0,0.26);
}

.co-btn.confirm:hover:not(:disabled) {
  background:
    rgba(255,255,255,0.19);

  border-color:
    rgba(255,255,255,0.38);

  transform:
    translateY(-1px);
}

.co-btn.confirm:disabled {
  opacity:
    .30;

  cursor:
    not-allowed;

  transform:
    none;

  box-shadow:
    none;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 599px) {

  #checkout-modal {
    padding:
      10px;
  }

  .co-panel {
    width:
      min(94vw, 420px);

    max-height:
      min(96dvh, calc(var(--checkout-viewport-height, 100dvh) - 20px));

    padding:
      20px 16px 16px;

    border-radius:
      24px;
  }

  .co-icon {
    width:
      42px;

    height:
      42px;

    margin-bottom:
      7px;
  }

  .co-title {
    font-size:
      18px;
  }

  .co-sub {
    font-size:
      10px;

    margin-bottom:
      12px;
  }

  .payment-methods {
    grid-template-columns:
      repeat(2, minmax(0,1fr));

    gap:
      6px;

    margin-bottom:
      11px;
  }

  .pay-btn {
    height:
      48px;

    flex-direction:
      row;

    gap:
      6px;
  }

  .pay-icon {
    width:
      18px;

    height:
      18px;
  }

  .co-total {
    font-size:
      29px;

    margin-bottom:
      11px;
  }

  .mixto-wrap,
  .cash-wrap {
    padding:
      9px 10px;

    margin-bottom:
      9px;
  }

  .mixto-row {
    grid-template-columns:
      58px 1fr;

    gap:
      6px;

    margin-bottom:
      5px;
  }

  .mixto-field {
    height:
      33px;

    font-size:
      14px;
  }

  .co-btn {
    height:
      41px;
  }
}
#toast {
  position:fixed; bottom:108px; left:50%; transform:translateX(-50%) translateY(14px);
  background:rgba(50,200,120,0.16); border:1px solid rgba(50,200,120,0.32);
  backdrop-filter:blur(18px); color:rgba(120,240,170,0.95);
  font-size:12px; font-weight:600; padding:9px 18px;
  border-radius:18px; z-index:9500; opacity:0;
  transition:opacity .2s, transform .2s; pointer-events:none; white-space:nowrap;
}
#toast.show { opacity:1; transform:translateX(-50%) translateY(0); }
#toast.warning {
  background:rgba(245,158,11,0.16);
  border-color:rgba(245,158,11,0.42);
  color:rgba(255,211,125,0.98);
  box-shadow:0 8px 28px rgba(245,158,11,0.18);
}

/* ── Tablet: catálogo a la izquierda y pedido fijo a la derecha ── */
@media (min-width:540px) and (max-width:1100px) {
  #app {
    grid-template-columns: minmax(0, 1fr) minmax(190px, 38%);
    grid-template-rows: 74px minmax(0, 1fr);
    grid-template-areas:
      "topbar topbar"
      "products order";
    padding: 10px;
    gap: 8px;
  }
  #top-bar,
  #products-panel,
  #order-panel { min-width: 0; }
  #top-bar { width: 100%; gap: 10px; }
  #top-user { gap: 8px; padding: 8px 10px; }
  #search-bar:focus-within { width: min(100%, 520px); }
  #product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }
  #order-panel {
    max-height: none;
    min-height: 0;
    overflow-y: auto;
  }
}

@media (max-width:539px) {
  /* No apilar el pedido debajo: el POS siempre conserva dos mitades. */
  #app {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-rows: 74px minmax(0, 1fr);
    grid-template-areas: "topbar topbar" "products order";
    padding: 10px;
    gap: 8px;
  }
  #order-panel {
    max-height: none;
    min-height: 0;
    overflow-y: auto;
  }
  #product-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  #search-bar:focus-within { width: min(100%, 520px); }
}
@media (max-width:520px) {
  #product-grid { grid-template-columns: repeat(2,1fr); gap:9px; }
  .prod-name  { font-size:13px; padding: 22px 10px 10px; }
  .prod-price { font-size:13px; padding: 3px 8px; top:7px; left:7px; }
  .dock-icon  { width:54px; height:54px; }
  .dock { gap:12px; padding:12px 16px; }
}

/* Algunos navegadores Android reducen el ancho CSS aunque la pantalla sea
   una tableta. Esta regla usa el ancho del dispositivo como respaldo. */
@media (min-device-width:600px) and (max-device-width:1400px) {
  #app {
    grid-template-columns: minmax(0, 1fr) minmax(190px, 38%);
    grid-template-rows: 74px minmax(0, 1fr);
    grid-template-areas:
      "topbar topbar"
      "products order";
    padding: 10px;
    gap: 8px;
  }
  #top-bar,
  #products-panel,
  #order-panel { min-width: 0; }
  #top-bar { width: 100%; gap: 10px; }
  #top-user { gap: 8px; padding: 8px 10px; }
  #search-bar:focus-within { width: min(100%, 520px); }
  #product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }
  #order-panel {
    max-height: none;
    min-height: 0;
    overflow-y: auto;
  }
}

/* ── POS fijo en tablet: nunca convertir el pedido en una fila inferior ── */
#app {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important;
  grid-template-rows: 74px minmax(0, 1fr) !important;
  grid-template-areas:
    "topbar topbar"
    "products order" !important;
  padding: 10px !important;
  gap: 8px !important;
}
#top-bar,
#products-panel,
#order-panel { min-width: 0; }
#top-bar { width: 100%; gap: 10px; }
#product-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 10px;
}
#order-panel {
  max-height: none !important;
  min-height: 0;
  overflow-y: auto;
}

/* ========== LOGIN SCREEN ========== */
#login-overlay {
  position:fixed; inset:0; z-index:99999;
  display:flex; align-items:center; justify-content:center;
  background: #000000;
}
#login-overlay.hidden { display:none; }
#init-loading {
  position:fixed; inset:0; z-index:100000;
  display:flex; align-items:center; justify-content:center;
  background:#000;
}
#init-loading.hidden { display:none; }
@keyframes spin-slow { to { transform:rotate(360deg); } }
.login-panel {
  background:linear-gradient(160deg,rgba(28,28,28,0.97),rgba(10,10,10,0.99));
  border:1px solid rgba(255,255,255,0.14); border-radius:32px;
  padding:52px 44px 42px; width:min(440px,94vw);
  box-shadow:0 32px 100px rgba(0,0,0,0.80), inset 0 1px 0 rgba(255,255,255,0.10);
  text-align:center;
}
.login-logo {
  font-size:30px; font-weight:900; letter-spacing:-.03em;
  background:linear-gradient(135deg,#ffffff,#e0e0e0,#c8c8c8);
  -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text;
  margin-bottom:6px;
}
.login-title { font-size:19px; font-weight:700; color:#ffffff; margin-bottom:4px; }
.login-sub { font-size:13px; color:var(--text-secondary); margin-bottom:30px; }
.login-field {
  width:100%; padding:15px 18px; border-radius:14px;
  border:1.5px solid rgba(230,115,30,0.30);
  background:rgba(14,10,30,0.88); color:var(--text-primary);
  font-size:16px; font-weight:600; outline:none; font-family:inherit;
  margin-bottom:12px; transition:border-color .15s; box-sizing:border-box;
}
.login-field:focus { border-color:rgba(210,95,20,0.88); background:rgba(16,12,36,0.90); }
.login-error { font-size:13px; color:#ff6b6b; font-weight:600; min-height:20px; margin-bottom:10px; }
.login-btn {
  width:100%; padding:18px; border-radius:16px; border:none;
  background:linear-gradient(180deg,#ffffff 0%,#d8d8d8 55%,#bdbdbd 100%);
  color:#111; font-size:17px; font-weight:800; cursor:pointer;
  font-family:inherit; transition:all .15s;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.58) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 8px 28px rgba(0,0,0,0.50),
    0 3px 8px rgba(0,0,0,0.28);
  letter-spacing:0.02em;
}
.login-btn:hover {
  transform:translateY(-2px);
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    -1px 0 0 rgba(255,255,255,0.58) inset,
    0 1px 3px rgba(0,0,0,0.18) inset,
    0 14px 36px rgba(0,0,0,0.55),
    0 4px 12px rgba(0,0,0,0.32);
}
.login-btn:disabled { opacity:.5; cursor:not-allowed; transform:none; }

/* ========== USER BADGE ========== */
.user-badge {
  display:flex; align-items:center; justify-content:space-between;
  padding:9px 14px; border-radius:13px;
  background:rgba(200,90,20,0.12); border:1px solid rgba(230,115,30,0.36);
  margin-bottom:10px; flex-shrink:0;
}
.user-badge-info { display:flex; flex-direction:column; gap:1px; }
.user-badge-name { font-weight:800; font-size:13px; color:var(--text-primary); }
.user-badge-caja { color:var(--text-secondary); font-size:11px; }
.logout-btn {
  padding:7px 16px; border-radius:10px;
  background:linear-gradient(180deg,#ffffff 0%,#d8d8d8 55%,#bdbdbd 100%);
  border:1.5px solid rgba(255,255,255,0.92); color:#111;
  font-size:11px; font-weight:800; cursor:pointer; transition:all .14s; font-family:inherit;
  box-shadow:
    0 2px 0 rgba(255,255,255,0.95) inset,
    0 4px 12px rgba(0,0,0,0.40),
