.oi-info {
  grid-column: 2;
  grid-row: 1;
  width: 100%;
}
.oi-name {
  font-size: 13px;
  line-height: 1.2;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
